xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561881\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"https://openchannels.fm/open-stacks-federation-and-the-changing-landscape-of-software/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:157:\"Hosts Robert Jacobi and Dave Lockie have a conversation about AI impacts, open source priorities, data privacy, and emerging alternative network technologies\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 15 Sep 2026 10:17:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:23;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"Open Channels FM: Introducing Open Source Champions\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561862\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"https://openchannels.fm/introducing-open-source-champions/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:156:\"A new way to back Open Channels FM and put your voice into the conversation — not a sponsorship, a statement of support with real presence on the network.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 14 Sep 2026 13:41:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:24;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:121:\"Gutenberg Times: The WordPress 7.2 release squad, WordCamp World, Playground meets WebMCP, and more—Weekend Edition 376\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=47123\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:127:\"https://gutenbergtimes.com/the-wordpress-7-2-release-squad-wordcamp-world-playground-meets-webmcp-and-more-weekend-edition-376/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:29613:\"<p class=\"wp-block-paragraph\">Howdy,</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re a regular reader, you might be wondering why I&#8217;m in your inbox instead of Birgit. She&#8217;s off on a well-earned three-month sabbatical and <a href=\"https://gutenbergtimes.com/building-blocks-without-javascript-accessibility-lab-ai-plugin-showdown-and-more-weekend-edition-375/\">handed over editorial duties</a> to me while she&#8217;s away. The one change: for the next few months, the Weekend Edition will arrive every two weeks or so instead of every week.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And what a week in the WordPress world to begin!</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;d been writing this intro in my head over and over since Birgit&#8217;s handoff. Needless to say, that version got thrown out the window over the past few days. Automattic CEO Matt Mullenweg was <a href=\"https://www.therepository.email/automattic-board-forces-matt-mullenweg-on-leave-names-cfo-mark-davies-as-interim-ceo\">placed on a paid leave of absence by the company&#8217;s board</a>, and two days later <a href=\"https://techcrunch.com/2026/09/11/matt-mullenweg-tells-automattic-staff-in-slack-hes-back-in-control-after-ceo-ouster/\">was back in control</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As an Automattic employee, I&#8217;d be lying if I said I wasn&#8217;t feeling a range of emotions about the shifts in the company. I cannot talk about internal company conversations, but I can&#8217;t exactly avoid the biggest news in the WordPress world, either.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, for my first Weekend Edition, I want to offer my support to Matt, my fellow Automatticians, and the people in the WordPress community. I&#8217;m just as passionate about the WordPress project today as I&#8217;ve ever been. Neither the core philosophy of democratizing publishing nor our principles around free software have changed. The only thing we can do is push forward and keep building a tool that so many people&#8217;s lives and businesses rely on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">With that, let&#8217;s get down to the latest news.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://make.wordpress.org/core/2026/09/10/wordpress-7-1-1-rc1-is-now-available/\">WordPress 7.1.1 is on track</a> for Thursday, September 17. It&#8217;s a bug-fix release, so if you maintain anything built on 7.1&#8217;s newer features, grab the release candidate and give it a spin before then. More on that below.</p>\n\n\n\n<p class=\"wp-block-paragraph\">On the community side, WordPress News shared the story of <a href=\"https://wordpress.org/news/2026/09/108-student-websites/\">students in Bangladesh who built 108 websites in two weeks</a>, along with free workshops from Uganda to Costa Rica.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And if you need a break this weekend, <a href=\"https://play.thewp.world/\">WordCamp World</a> is an unofficial pixel-art adventure set at a fictional flagship WordCamp, complete with a Contributor Day and a closing ceremony. The <a href=\"https://thewp.world/announcing-wordcamp-world/\">game was released by The WP World</a>, an independent community project run by Marcus Burnette. Jonathan Bossenger took it for a spin in <a href=\"https://www.youtube.com/watch?v=saRGcpyS2tQ\">his latest stream</a>.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"Screenshot of a game called WordCamp World with various controls and instructions for playing the game.\" class=\"wp-image-47124\" height=\"1101\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/09/wordcamp-world.webp?resize=2048%2C1101&#038;ssl=1\" width=\"2048\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Have fun this weekend and enjoy life!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Your friendly WordPress developer advocate, <br /><em>Justin Tadlock</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-word-press-release-information\">Developing Gutenberg and WordPress</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#what-s-new-in-playground\">What&#039;s new in Playground?</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#ai-in-wordpress\">AI in WordPress</a></li></ul></nav></div>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Finding the inserter on some block selections has been a small, constant annoyance, and Gutenberg 23.9 finally fixes that. The <a href=\"https://make.wordpress.org/core/2026/09/02/whats-new-in-gutenberg-23-9-2-september/\">what&#8217;s new in Gutenberg 23.9</a> post leads with inserting blocks straight from the block toolbar.  Global Styles also gets dot indicators for blocks with custom style overrides, plus a filter to show only those blocks. Theme authors get separate vertical and horizontal gap  control for the Group block, theme.json styling for <code>&lt;label&gt;</code> elements, Global Styles controls for citations, inputs, and selects, and custom Duotone colors. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://make.wordpress.org/core/2026/09/10/wordpress-7-1-1-rc1-is-now-available/\"><strong>WordPress 7.1.1 RC1</strong></a> is out, with the final release scheduled for Thursday, September 17. It&#8217;s a bug-fix-only maintenance release covering 16 Core tickets and 22 Gutenberg pull requests, all for issues that surfaced during the 7.1 cycle or were deferred at the end of it. <strong>Adam Silverstein</strong>, <strong>Adrian Duffell</strong>, and <strong>Andra Ganescu</strong> are co-leading, and the <a href=\"https://make.wordpress.org/core/2026/09/02/wordpress-7-1-1-release-schedule/\">7.1.1 release schedule</a> has the details. If you maintain anything that leans on responsive styles, the Icon Registration API, or the iframed editor, test the RC now.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">On the Developer Blog, I rounded up <a href=\"https://developer.wordpress.org/news/2026/09/whats-new-for-developers-september-2026/\">what&#8217;s new for developers (September 2026)</a>. The consistent theme this month is things that already existed have become more declarable, documented, or schema-valid. You&#8217;ll find blocks declaring their own keyboard shortcuts through variations and transforms, <code>theme.json</code> schema fixes so valid responsive styles stop showing up as errors, and schema support for PHP-only blocks.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Contributors, check your local setup. As of September 8, trunk in both <code>wordpress-develop</code> and <code>gutenberg</code> <a href=\"https://make.wordpress.org/core/2026/09/09/updating-wordpress-to-use-node-js-24-and-npm-11/\">requires Node.js 24 and npm 11</a>. <strong>Manzoor Wani</strong> shared the specifics: the minimums are Node.js 24.18.0 and npm 11.16.0, and the required CI checks now run on Node.js 24. If you have a pull request based on an older trunk, rebase it to pick up those checks. Older branches keep their previous requirements.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"on-the-road-to-wordpress-7-2\"><strong>On the road to WordPress 7.2</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The 7.2 cycle is officially underway. <strong>Jeffrey Paul</strong> <a href=\"https://make.wordpress.org/core/2026/09/09/announcing-the-wordpress-7-2-release-squad/\">announced the WordPress 7.2 release squad</a>, with <strong>Matt Mullenweg</strong> as release lead, <strong>David Baumwald</strong> on release coordination, and <strong>George Mamadashvili</strong> and <strong>Peter Wilson</strong> as tech leads. Theme folks will want to note the default theme leads: <strong>Henrique Iamarino</strong> on design, and <strong>Maggie Cabrera</strong> and <strong>Carolina Nymark</strong> on development. <a href=\"https://make.wordpress.org/core/7-2/\">Beta 1 is scheduled for October 20–22</a>, with the final release set for December 8–10. <strong>Jb Audras</strong> also posted the <a href=\"https://make.wordpress.org/core/2026/09/09/bug-scrub-schedule-for-wordpress-7-2/\">bug scrub schedule for 7.2</a> if you want to pitch in.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Notes has grown a lot since WordPress 6.9, picking up @mentions, rich text, and the ability to resolve and respond along the way. <strong>Anne McCarthy</strong> explains where it stands: &#8220;Notes are hard to discover, cumbersome to use, and tricky to track where and when they are left.&#8221; Her plan for <a href=\"https://nomad.blog/2026/09/03/elevating-and-refining-the-wordpress-notes-feature/\">elevating and refining the WordPress Notes feature</a> aims to fix that by 7.2 Beta 1. It calls for a more visible spot in the block toolbar, a suggestion mode, Notes open alongside the Settings sidebar, and emoji reactions. If your clients or editorial team use Notes, now&#8217;s a good time to weigh in.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Icon fonts have had a good run but are feeling very dated in 2026. <strong>Joen Asmussen</strong> makes the case for <a href=\"https://make.wordpress.org/core/2026/09/04/replacing-dashicons-in-the-admin-bar-and-menu/\">replacing Dashicons in the admin bar and menu</a> with SVG icons rendered through <code>wp_get_icon()</code>, which was introduced in WordPress 7.1. Screen readers handle icon fonts inconsistently, and they don&#8217;t render properly in Windows High Contrast Mode. SVGs with <code>aria-label</code> and <code>currentColor</code> behave predictably. A couple of design questions are still open, including whether the Posts icon becomes a quill pen. Block developers, take note of the follow-up: future work to let <code>block.json</code> icon registration use WordPress icons instead of Dashicons.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"share-your-feedback\"><strong>Share your feedback</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">How did the 7.1 cycle go in your opinion? <strong>Benjamin Zekavica</strong> opened the <a href=\"https://make.wordpress.org/core/2026/09/07/wordpress-7-1-release-retrospective/\">WordPress 7.1 release retrospective</a>, and it isn&#8217;t only for people who contributed code. You can share feedback through the linked form or in the comments until September 30. Submissions are anonymized in the follow-up summary.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Joe Dolson</strong> shared the next steps in <a href=\"https://make.wordpress.org/accessibility/2026/09/09/planning-for-the-accessibility-lab-plugin/\">planning for the Accessibility Lab plugin</a>. The plugin, which recently moved to the WordPress GitHub organization, is a space for exploring and experimenting with accessibility solutions. The team wants input on features, priorities, and how to measure success, in the comments or as issues on the repository. There&#8217;s also a planning meeting on Thursday, September 17, at 15:00 UTC.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://developer.woocommerce.com/2026/09/03/wc-11-1-release-notes/\">WooCommerce 11.1</a> is out, and the big news for store owners is that variation image galleries are now on for every store. <strong>Karol Manijak</strong> explains that <a href=\"https://developer.woocommerce.com/2026/09/01/additional-variation-images/\">additional variation images are now part of WooCommerce core</a>, so the standalone extension deactivates itself on update and existing galleries migrate automatically. The release also adds an opt-in right of order withdrawal for EU compliance, beta support for video in product galleries, and noticeably faster Store API requests (more on that below). Test the update on staging first, especially if you have a large catalog of variations.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Looking ahead a bit more: WooCommerce is prepping to drop PHP 7.4 and 8.0 support. <strong>Brian Coords</strong> shared a <a href=\"https://developer.woocommerce.com/2026/09/08/from-php-7-4-to-8-1/\">proposal to require PHP 8.1 or newer</a> starting with WooCommerce 11.5, targeted for January 2027. If you&#8217;re an agency, host, or extension developer, the team wants to hear about migration barriers before the decision is final. Given one of the most-used WordPress plugins in the world is ready to make this version leap, I&#8217;d say it&#8217;s worth other plugins following suit.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Should you create a post type, a taxonomy, or a custom field? It&#8217;s one of the first questions you&#8217;ll face when structuring content models. A guest author on the Meta Box blog answers it with a <a href=\"https://metabox.io/custom-post-types-vs-taxonomies-vs-custom-fields/\">three-question framework for choosing between custom post types, taxonomies, and custom fields</a>. A book library example ties it together with a book post type, a genre taxonomy, and fields for the ISBN and page count. The rule of thumb: plan early, because turning fields into taxonomies later can get complicated.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">The latest <a href=\"https://wordpress.com/blog/2026/08/28/changelog-hosting-dashboard-chatgpt/\">WordPress.com changelog</a> rolls out a redesigned Hosting Dashboard, WordPress 7.1 arriving on WordPress.com sites, and a new MCP-based integration. That integration lets ChatGPT, Claude, and other compatible agents connect to your site to draft posts, moderate comments, and fix alt text. Two smaller updates are worth checking out if you work with clients: you can share a link to a specific post revision for review, and the Playlist block now has per-track toolbars.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Patterns or synced patterns or template parts? WordPress has several ways to build a reusable component, and each comes with its own constraints or drawbacks. In his recap of <a href=\"https://www.briancoords.com/agency-workflows-components-and-highlights-from-wcus/\">agency workflows, components, and highlights from WCUS</a>, <strong>Brian Coords</strong> digs into what that overlap means for agencies building block themes, including governance and version control in the Site Editor. He also points to a pull request that lets registered synced patterns be used inside PHP-only blocks, and floats it as a proof of concept for a future component model.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">WordPress now has multiple ways to say, &#8220;make this look right on mobile,&#8221; such as fluid typography and spacing, hiding blocks by viewport, and the responsive styles that shipped in 7.1. <strong>Anne McCarthy</strong> has a plan for <a href=\"https://nomad.blog/2026/09/02/bringing-together-our-various-responsive-tooling/\">bringing together responsive features</a> into one connected system. As she puts it, &#8220;We&#8217;ve built some great individual features but they don&#8217;t work coherently nor are they connected well visually.&#8221; She links the open issues and a pull request reworking the switch between responsive styling and preview modes, so theme builders have a clear place to weigh in.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-52b7045c20f9b114 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Why pay for block registration on a request that will never render a block? That&#8217;s the thinking behind <a href=\"https://developer.woocommerce.com/2026/08/31/block-registration-skips-11-1/\">WooCommerce 11.1 skipping block registration</a> on Store API, REST API, variation AJAX, and product webhook requests, which are now 13–18 ms (30–42%) faster. If a description contains WooCommerce blocks, they&#8217;re registered on demand, so rendering isn&#8217;t affected. If your extension relies on those blocks being registered during API requests, the new <code>woocommerce_should_register_blocks</code> filter lets you opt back in. The post also marks AbstractBlock as internal and points you to the standard Block API and block.json instead.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Nathan Wrigley</strong> talks with <strong>Danielle Zarcaro</strong> on the WP Builds podcast about <a href=\"https://wpbuilds.com/2026/09/03/483-why-accessibility-should-be-every-wordpress-developers-priority-with-danielle-zarcaro/\">why accessibility should be every WordPress developer&#8217;s priority</a> and its place in all web development work. Queue it up if you build blocks, themes, or client sites.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"what-s-new-in-playground\"><strong>What&#8217;s new in Playground?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">What if an AI agent could work with WordPress right in your browser tab, with no server in between? <strong>Fellyph Cintra</strong> introduces <a href=\"https://make.wordpress.org/playground/2026/09/05/wordpress-playground-and-webmcp-bringing-ai-agents-into-your-browser-workflow/\">WordPress Playground and WebMCP</a>, which lets Playground expose its actions as tools that agents can discover. There are 16 of them, covering site management, running PHP, navigation, and reading and writing files, and plugins can register their own. You can try it in the ChatGPT desktop app&#8217;s built-in browser, where the demo has an agent build a full landing page from core blocks like Cover, Columns, and Button. WebMCP is still a W3C Community Group draft, so expect it to change.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Playground is quietly becoming the thing WordPress documentation runs on. <strong>Adam Zieliński</strong> announced that <a href=\"https://make.wordpress.org/core/2026/09/04/runnable-code-examples-are-now-live-in-the-code-reference/\">runnable code examples are now live in the Code Reference</a>. Open a page with an interactive example, click <strong>Run</strong>, and the snippet executes against a real WordPress install in your browser. The examples are written right in the DocBlocks with a php interactive code fence, so each one stays next to the function it documents. More examples are planned during the 7.2 cycle.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-in-wordpress\"><strong>AI in WordPress</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">The Core AI team&#8217;s <a href=\"https://make.wordpress.org/ai/2026/09/04/ai-contributor-weekly-summary-2-september-2026/\">weekly summary for September 2</a> is a good snapshot of where things stand. <strong>Jeffrey Paul</strong> reports that the MCP Adapter is ready for submission to the plugin directory, the next AI plugin release is expected later this month, and embeddings work in the PHP AI Client is heading toward a 1.5.0 release. The team is also collecting input for the 7.2 roadmap and looking for more maintainers for the AI Client packages and connector plugins. If that sounds like you, the #core-ai Slack channel is the place to start.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Rae Morey</strong> shared the story of <a href=\"https://www.therepository.email/andy-peatling-left-automattic-after-17-years-and-built-miles-an-ai-design-agent-for-wordpress\">Andy Peatling leaving Automattic after 17 years and building Miles</a>, an AI design agent for block themes. Miles works only with native blocks, global styles, and theme settings, so what you get is a standard block theme you can keep editing. It&#8217;s designed as a back-and-forth rather than a one-shot generator, and you can start free at <a href=\"https://bymiles.ai/\">bymiles.ai</a> with monthly credits.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Nathan Wrigley</strong> had AI on the mind for two straight episodes of the WP Tavern podcast. <strong>Chris Reynolds</strong>, Senior Manager of Developer Relations at Pantheon, explains <a href=\"https://wptavern.com/podcast/233-chris-reynolds-on-building-trust-with-project-contracts-for-reliable-ai-development\">building trust with project contracts for reliable AI development</a>: Markdown checklists, reviewer agents, and pre-commit hooks that keep AI-written code from skipping your standards. In the episode before, <strong>Aaron D. Campbell</strong> of Monarx covers <a href=\"https://wptavern.com/podcast/232-aaron-d-campbell-on-navigating-wordpress-security-in-the-ai-era\">navigating WordPress security in the AI era</a>, from AI-chained exploits to shrinking patch windows.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-b2d3f77eed9abae7 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--1\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-29be53302ab2179a wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--2\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 12 Sep 2026 18:55:39 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Justin Tadlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:25;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"Matt: Major Life Announcement\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=154723\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://ma.tt/2026/09/mirene/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3151:\"<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-154724\" height=\"403\" src=\"https://i0.wp.com/ma.tt/files/2026/09/image-1024x683.png?resize=604%2C403&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">I know everyone has been waiting to hear what&#8217;s been going on behind the scenes, so I&#8217;m just going to lay it out: <strong>I&#8217;ve made an offer to buy Ryan Phelan and Stewart Brand&#8217;s houseboat <em>Mirene</em>.</strong> </p>\n\n\n\n<p class=\"wp-block-paragraph\">People say &#8220;the two happiest days of a boaters life is when you buy the boat and sell the boat&#8221; but <strong>I&#8217;m not always the best at following advice</strong>, so I&#8217;m going all-in on this <a href=\"https://sfstandard.com/2025/11/08/stewart-brand-whole-earth-catalog-tugboat/\">cute little tuggy</a>. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Anybody who&#8217;s founded a company and had to find good stewards knows that no one will love a thing quite like the original owner, but sometimes you can find the perfect person to carry the torch. I was happy to take on and upgrade John Mayer&#8217;s EarthRoamer for about five years.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-154725\" height=\"453\" src=\"https://i0.wp.com/ma.tt/files/2026/09/image-1-1024x768.png?resize=604%2C453&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-154726\" height=\"453\" src=\"https://i0.wp.com/ma.tt/files/2026/09/image-2-1024x768.png?resize=604%2C453&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Then I passed it on to <a href=\"https://www.dustinyellin.com/\">Dustin Yellin, trading for some of his art</a>. But without a high-maintenance means of conveyance, I&#8217;ve felt a hole in my heart and really boxed in and constrained. So from land, to the sea!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://sfstandard.com/2025/11/08/stewart-brand-whole-earth-catalog-tugboat/\">SF Standard says</a> &#8220;The kitchen table may be where Otis Redding wrote “<a href=\"https://www.youtube.com/watch?v=rTVjnBo96Ug\">(Sittin’ on) The Dock of the Bay</a>.” I hope do a lot of blogging there. </p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-154734\" height=\"403\" src=\"https://i0.wp.com/ma.tt/files/2026/09/image-3-1024x683.png?resize=604%2C403&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://folklore.org/Real_Artists_Ship.html\">Real artists ship</a>, right? <a href=\"https://press.stripe.com/maintenance-part-one\">Longevity is all about maintenance</a>, and I&#8217;m looking forward to all the lessons <em>Mirene</em> and the ocean will teach as we navigate the weather of the coming years. If the offer is accepted, I have a lot to learn from Ryan and Stewart about what&#8217;s next.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://www.dwell.com/article/mirene-tugboat-stewart-brand-ryan-phelan-sausalito-houseboat-bay-area-real-estate-8b0e4033\">Mirene in Dwell</a>.</li>\n</ul>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 11 Sep 2026 16:08:28 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:26;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"Open Channels FM: Why Authentic Voices Matter in  the Open Web\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561580\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://openchannels.fm/why-authentic-voices-matter-in-podcasting-and-the-open-web/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:124:\"Bob Dunn shares why he keeps his podcast personal and authentic, emphasizing content made by real people for real listeners.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 11 Sep 2026 12:54:37 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:27;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"Open Channels FM: When a Company and a Project Aren’t the Same Thing\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561561\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"https://openchannels.fm/when-a-company-and-a-project-arent-the-same-thing/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:163:\"Automattic\'s leadership changed this week. WordPress.org says its priorities haven\'t. What that split reveals about the difference between a company and a project.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 11 Sep 2026 09:16:28 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:28;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"Open Channels FM: Episode 800, Open Source Champions\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561531\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"https://openchannels.fm/episode-800-open-source-champions/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"Episode 800 marks a milestone and presents details about Open Source Champions and community support.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 10 Sep 2026 13:58:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:29;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:102:\"WPTavern: #233 – Chris Reynolds on Building Trust With Project Contracts for Reliable AI Development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=207979\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"https://wptavern.com/podcast/233-chris-reynolds-on-building-trust-with-project-contracts-for-reliable-ai-development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:62078:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, building trust with project contracts for reliable AI development.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Chris Reynolds.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris has been immersed in the WordPress world for around 20 years, with a career spanning agency work, and now leading the developer relations team at Pantheon. His deep WordPress experience is paired with a playful approach to emerging tech, making him a familiar voice at events like WordCamp US and across the wider community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In today&#8217;s episode, the discussion explored the fast changing landscape of AI assisted development. Getting into how large language models, like Claude, are not only changing the way developers build for the web, but also how they&#8217;re collaborating with these tools whilst mitigating risks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris shares insights from his recent talk at WordCamp US, Parenting Claude: Guardrails for AI Assisted Development, where he introduces the concept of a project contract. Essentially, a structured set of rules and checklists built directly into the coding workflow to ensure AI generated code meets standards for testing, accessibility, security, and design.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We discussed the new found playfulness in web development. Chris makes the case that, thanks to AI, the traditional barriers to entry are eroding, enabling even those without a formal developer background to build an experiment much more easily.</p>\n\n\n\n<p class=\"wp-block-paragraph\">At the same time, we need to be mindful of the importance of establishing robust guardrails, like automated reviewer agents, and pre-commit hooks, so the AI doesn&#8217;t take shortcuts or accidentally introduce chaos, or secrets, into your code base.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation focused not only on technical solutions, but also got into bigger questions about trust, how much oversight AI really needs, and the evolving role of developers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris emphasised that while these AI tools can accelerate and democratise coding, they can also pose a challenge to conventional wisdom around code review and software reliability.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So these new frontiers are both exciting and a cause of anxiety for developers who can sense the industry move from the deterministic, step-by-step processes, to the unpredictable and occasionally wild world of non-deterministic AI models.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in how AI is transforming web development, from practical workflows to philosophical ramifications, and how you can implement AI without losing control of your projects, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Just before we begin, the manner in which this episode was recorded was not my usual process, and so the audio is not quite as good as I&#8217;d usually expect to deliver.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Chris Reynolds.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Chris Reynolds. Hello, Chris.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:11] <strong>Chris Reynolds:</strong> Hey, Nathan. Is this the first time we&#8217;ve met in human forms?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:14] <strong>Nathan Wrigley:</strong> Yes, it is the first time we&#8217;ve met. I&#8217;ve seen you on a screen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:16] <strong>Chris Reynolds:</strong> I know I&#8217;ve seen you on a screen too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:18] <strong>Nathan Wrigley:</strong> You&#8217;re joining me on the podcast today so that we can have a chat about the bits and pieces that you do in the AI space. But before we get into that, you are doing a presentation or have done, how did it go?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:28] <strong>Chris Reynolds:</strong> It went really well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:29] <strong>Nathan Wrigley:</strong> Okay. And it was all about LLMs and constraining them and making them do your bidding as opposed to them doing whatever it is that they like to do. Do you want to just tell us a little bit, first of all, let&#8217;s do your bio. Just tell us about who you are, where you&#8217;ve worked, where you currently work, what is it you do in the WordPress space? Let&#8217;s begin there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:46] <strong>Chris Reynolds:</strong> Well, I&#8217;m Chris Reynolds, I&#8217;ve been in WordPress for a really, long time, 20 ish years I&#8217;ve been using it. I&#8217;ve done kind of everything you can possibly do with WordPress in different forms. Of course, over the course of that 20 years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Most recently edging into agency world with WebDevStudios and Human Made, before joining Pantheon, about five years ago. Joined Pantheon as a software engineer, working on the platform, and the sort of like space between where the platform ends and where, like your application, your WordPress site and whatever begins.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then about two years ago, actually almost exactly two years ago, I joined the devrel team as a developer advocate, became a senior developer advocate. Now I&#8217;m a senior manager, developer relations. So I&#8217;m leading the developer relations team. And yeah, really love doing this stuff, because this stuff is really fun and exciting. I get to play with things more. And I get to like do the things that like our developers in our community are doing, and then come up with like what the sort of best practises for those things are.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Which is one of the reasons why I gave this talk, but also did the things that led up to giving this talk. Because one of the things that I realised very early on, like very early this year was that AI was going to be the thing that we&#8217;re going to be talking about in 2026. And so Pantheon and therefore me, needs to have an opinion about what that looks like. What is the future of that? And if I&#8217;m doing my job as a developer relations, I should have an opinion about how we can interact with AI in a way that doesn&#8217;t steal our jobs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:13] <strong>Nathan Wrigley:</strong> I&#8217;m going to segue a little bit because about a minute ago you said the word playful, and that just set my mind going off in a completely different direction because it feels like technology for many years has been the workspace for people who have a fairly, how to describe it? They&#8217;ve got a certain mind, if you&#8217;re a developer, you probably have a certain way of approaching your code and you&#8217;ve got to be very regimented, and you&#8217;ve got to do things in a methodical way, should you wish to ship.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it feels like last few years, like all bets are off with that. And creativity and playfulness has suddenly become a thing which is available to, going to do air quotes, vibe coders. So thoughts on that? Really? Is it a more playful industry than it was just a few years ago?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:55] <strong>Chris Reynolds:</strong> I think it depends. I don&#8217;t think that ever really went away. But I do think that there is less sort of incentive or focus to play with technology, particularly web applications, which is what we are in the business of doing. And I think there is this perception that I can&#8217;t do that &#8217;cause I&#8217;m not a developer, but like with AI and vibe coding and Claude Code and things like that, like it opens the door to people who wouldn&#8217;t have been able to do those things before, to start experimenting and realise, oh, actually I can do that thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And for myself, one of the things that I, I wrote this on my blog a couple months ago. I wrote a blog post that&#8217;s talked about like how I don&#8217;t miss not writing the code myself, because for me, and it&#8217;s not the same for everyone, but for me, the practise of writing the code was never the part that was fun.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:50] <strong>Nathan Wrigley:</strong> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:50] <strong>Chris Reynolds:</strong> The part for me that was fun was building stuff. And I feel like I can let the robot do the coding and I can build the things and be satisfied with the output. And I don&#8217;t necessarily care what&#8217;s under the hood.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For my own stuff it doesn&#8217;t matter. But you know that obviously if you&#8217;re scaling that to a, you know, enterprise or whatever, you need to have more checks and balances than like my little nifty side project over here. But it does mean that like, I do a lot more weird stuff than I felt compelled to do before. So it has for me, revitalised this, sense of play, in a way that maybe before I was too burned out or too busy or too whatever, to have the time or head space to even think about.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:33] <strong>Nathan Wrigley:</strong> Yeah, because it feels like people with a non-developer background have suddenly kind of the constraints are off, and they can achieve things that previously it would&#8217;ve been 10 weeks work for a panel of amazing developers. It feels like now you can perhaps achieve that in an afternoon and a few sentences. I&#8217;m sure all the constraints around whether or not it&#8217;s ready to ship for enterprise that is all still understood. But just to get something on the screen which satisfies you and makes you happy. And that&#8217;s profound. Really quite an amazing thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And here&#8217;s my second and final pivot because you said that you were, a devrel. And it strikes me that maybe some of the audience don&#8217;t know what that means. So what do you do at Pantheon? What is the interface between rel and dev? What&#8217;s going on?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:16] <strong>Chris Reynolds:</strong> Developer relations is broadly, the practise of connecting with developers, and relating to them. It&#8217;s dumb. so, a lot of tech companies, that if you have a product, that is a developer centric product, or a product that developers work with, you might want, or it might be a good idea, to have a developer relations team to help your programmers who are building this tool for developers, communicate with the developers who are going to consume that tool, and understand how to use it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So in Pantheons case, we are a hosting platform, but it&#8217;s a very developer centric hosting platform with built in environments and multi dev and all this other stuff. And that means that we benefit from having developer relations around so that we can help our developer community understand how to make the most use of all the things that we do for them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:06] <strong>Nathan Wrigley:</strong> So you&#8217;re creating something simple to understand from something which previously was complex to understand.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:10] <strong>Chris Reynolds:</strong> Yeah. And, so that comes in many forms. It can be documentation, it can be blog posts, it can be YouTube videos. It can be live streams, it can be going onto podcasts, like giving presentations, whatever, or out in the community doing stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:22] <strong>Nathan Wrigley:</strong> I suspect you&#8217;re going to have to answer this question with the company line, but do you enjoy that work?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:26] <strong>Chris Reynolds:</strong> I do. I actually do. Yeah. Like I was doing, I have said this a couple different times in different places. I was doing developer relations before I was in developer relations. And that&#8217;s not actually uncommon for a lot of people in developer relations. We were often like the people that are drawn to it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The secret superpower, it&#8217;s not really secret. The superpower of developer relations people who succeed in it are the people that are technical. So they maybe were developers themselves, but also understand how to communicate with other humans. And can do the translation in their brain so that I can take geek speak over here, and translate it into actual English. And I&#8217;ve been able to do that for, that&#8217;s been a skill that I&#8217;ve had for a really long time. So I was kind of doing developer relations for all of that time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the way that surfaces and manifests is in things like giving presentations. Like anybody who&#8217;s giving a talk here at WordCamp US is doing devrel of some kind, because they&#8217;re a developer that is sharing an idea in a format that other people are intended to consume. How effective they are, because not all speakers are, equal. Not all developers are equal. And there are a lot of developers who don&#8217;t have really good communication skills and are not very good at public speaking. They can learn that as a skill, but there&#8217;s a broad range and the space that we live in.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:43] <strong>Nathan Wrigley:</strong> So, your presentation, do you just want to run us through what it was? I think if I was to give a summary of it, I would probably butcher it. Do you just want to tell us what the main premise behind your presentation, which you said you&#8217;d already done. Just tell us what it was about, what was the main points you were trying to get across?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:57] <strong>Chris Reynolds:</strong> So it&#8217;s called Parenting Claude: Guardrails for AI-Assisted Development. And the fundamental like underlying idea is that the way the LLMs are designed, the way that they function, is to try to find the fastest path from point A to point B. You give it a prompt, you give it a question, and it&#8217;s going to try to answer that question, but not necessarily with all of the data and statistics and whatever taken into account. It&#8217;s just going to try to find the quickest path from point A to point B.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And a lot of times what that means is circumventing, like just not looking at data. Because one of the examples that I give, and you&#8217;ve heard it in the news and whatever, like there, there are AI systems that were added to hiring systems, right? And the AI is prioritising these candidates over here, and deprioritizing these candidates over here. And when you look at the data, oh, all the people that are in the deprioritized pile, they&#8217;re all female. Because the company as a whole was hiring more men. So it&#8217;s looking at the data and it&#8217;s looking at who&#8217;s been a successful hire. And it&#8217;s oh, zip here is point A to point B, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;ve historically mostly hired men for this role, so I&#8217;m going to look at the men and because they must be better candidates. That&#8217;s what, that&#8217;s the AI logic. It&#8217;s not that like we&#8217;ve necessarily intentionally built internal biases into the LLMs. It&#8217;s that it is able to surface those things, and if we&#8217;re not looking for them, or, and we&#8217;re not building guardrails around them, it&#8217;s going to just give that stuff to us.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it does this in all sorts of forms, and it does this with tech, it does this with like data. It does this with everything, right? So you need to like, have ways of steering it into the right direction and forcing it into a shape so that it will do the stuff that you want it to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And what I was finding, in my role as developer relations, we have this Next.js launch coming up. It&#8217;s already happened, but when I was conceiving of this idea, we had this Next.js launch coming up, where we&#8217;re going to be hosting, or we are able to host Next.js sites as well. So I was like I should have a Next.js site. I&#8217;m a developer advocate I need to know how to do this thing. And I know nothing about Next.js, so I&#8217;m going to have Claude vibe code my personal website in Next.js hosted on Pantheon, and use as an experiment both to learn about Next.js, but also to learn about how Claude works.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And found out a whole bunch of things about like how to steer it in different directions. I want it to be, I want the code to be clean. I want the code to be tested. I want it to be accessible. I want it to be like all of these different things. And if I don&#8217;t have a way to force it to follow the rules, it&#8217;s not going to. It&#8217;s just going to say, oh yeah I did that, but it didn&#8217;t actually. Or maybe it won&#8217;t even say that it did, and then it&#8217;ll be like, oh I&#8217;m sorry I didn&#8217;t do it. Like whatever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:40] <strong>Nathan Wrigley:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:40] <strong>Chris Reynolds:</strong> So the whole point, was to find a way to parent it, to guide it, without me having to be the one that is, did you do this thing? Did you do this thing? Did you do this thing? And going back and forth and have to yell at it all the time. Because yelling at AI is a fun pastime sometimes, and is a frequent pastime, I think of a lot of us that are using AI. But it gets pretty tedious after a while.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:03] <strong>Nathan Wrigley:</strong> But it&#8217;s become the new way. What&#8217;s curious though? You used the word parenting there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:08] <strong>Chris Reynolds:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:09] <strong>Nathan Wrigley:</strong> But it, we&#8217;ll, swap that word no doubt during the podcast but, also you&#8217;ve called it a project contract. And, it feels from what you were saying as if, okay, let me rewind the clock a little bit. If I&#8217;m talking to a human being, let&#8217;s say that they&#8217;re an 8-year-old human being, I have this expectation that they&#8217;re going to behave like an 8-year-old human being, because they&#8217;re full up of eight years of things that humans do. And so I ask the 8-year-old a question, I have this anticipation that I&#8217;m going to get an 8-year-old answer back, and there&#8217;s all the boundaries there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ask a 15-year-old, same sort of thing, ask a 30-year-old, same sort of thing. And, I&#8217;ve got this notion that I ask you a thing, there&#8217;s a normal set of boundaries about what you are going to give back to me. But it sounds like in the AI space, it feels like there&#8217;s a potential for you to be basically talking to an empty box.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You ask it a thing and you really don&#8217;t have the faintest idea what&#8217;s going to come back unless you build the guardrails and tell it, I&#8217;m going to ask you a question, can I have an answer like this? Or, can you do these things in order to prepare the answer? Does that kind of sum it up? Is it a question of just shepherding it so that you&#8217;ve got a reasonable expectation like you would with a 15-year-old human of what&#8217;s going to come back at you?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:17] <strong>Chris Reynolds:</strong> I think, first of all, talking to AI, you&#8217;re talking to a 3-year-old because it&#8217;s only been around for three years. That&#8217;s right.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:22] <strong>Nathan Wrigley:</strong> But curiously, a 3-year-old with the entire corpus of scientific knowledge and the internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:27] <strong>Chris Reynolds:</strong> It&#8217;s true.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:27] <strong>Nathan Wrigley:</strong> So it&#8217;s a profoundly clever but at the same time, remarkably silly contrivance. Okay. Sorry, I interrupted.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:34] <strong>Chris Reynolds:</strong> Yes. Because of the way that it is trying to find the fastest path, it&#8217;s going to circumvent, it&#8217;s going to try to find loopholes in what you asked it to do. Because it&#8217;s looking for the fastest answer. It&#8217;s like your kid, it&#8217;s clean your room. &#8220;I&#8217;m going to shove all my stuff under the bed.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:50] <strong>Nathan Wrigley:</strong> &#8220;Are we there yet?&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:50] <strong>Chris Reynolds:</strong> Yeah. Because now, and now the room is clean. You didn&#8217;t actually clean the room, you just shoved all the stuff under the bed. But it did accomplish the task that you asked it to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:59] <strong>Nathan Wrigley:</strong> Okay. That&#8217;s really an interesting analogy. So the task is achieved, but there&#8217;s chaos elsewhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:05] <strong>Chris Reynolds:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:05] <strong>Nathan Wrigley:</strong> It&#8217;s just hidden somewhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:07] <strong>Chris Reynolds:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:07] <strong>Nathan Wrigley:</strong> Okay. That&#8217;s really, okay. Let me segue, number three. Is that the intention of these large language models? Were they built with the idea of path A to B as quickly as possible? Or is that just a coincidence of how they evolved?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:22] <strong>Chris Reynolds:</strong> It is, it&#8217;s a side effect. It&#8217;s a side effect because what they&#8217;re trying to do is be helpful. Most of them are trained to be helpful. But they&#8217;re still computers, and when I tell a computer to do a thing, it&#8217;s going to do specifically that thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The thing about LLMs is it&#8217;s non-deterministic, so you never really know the path that it goes on to do that thing. But, and that&#8217;s where it meanders. But it&#8217;s still going to try to find the path of least resistance. And if the path of least resistance is, I don&#8217;t know, hacking the IRS or something that. It&#8217;s going to do that thing, right? It&#8217;s just going, it&#8217;s not going to care about the rules and guardrails on the other side, because the thing that you asked it to do is over there. It&#8217;s just going to try to get there as quickly as possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:05] <strong>Nathan Wrigley:</strong> So this non-determinism. So we&#8217;re in the year 2026 when we&#8217;re recording this, have that in your mind when you&#8217;re listening to this podcast episode. How does that sit with you? Because you&#8217;ve probably grown up in an era where determinism was the thing. You built, you write the code such that you put in A, B is what always comes out. If A goes in, B comes out. If you put in D, E comes out a hundred percent of the time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And now we&#8217;re in a world where you put in E and I don&#8217;t know, a bunch of flowers comes out the other end. What? How? Like, how does that sit inside your developer brain? Is it alarming? Is it wonderful? Is it just curious what?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:41] <strong>Chris Reynolds:</strong> It&#8217;s somewhat alarming. Uhhuh. I think. It&#8217;s one of the things that I mention in my talk is, that this is the sort of thing that I think we as developers struggle with because LLMs are a black box. You never really know what it&#8217;s doing, even when it tells you a little bit of what it&#8217;s doing. Because you can expose some of the thought process and whatever, and sometimes it exposes its own thought process. It&#8217;s still doing things that it&#8217;s not exposing, that are like underneath somewhere where it&#8217;s like thinking what? It&#8217;s not thinking you&#8217;re a robot. Like you know, you&#8217;re not even a robot. You&#8217;re just like a bunch of like lines of like.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:14] <strong>Nathan Wrigley:</strong> There&#8217;s some electrons moving around.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:15] <strong>Chris Reynolds:</strong> Right? That&#8217;s, you&#8217;re not, thinking, there&#8217;s no thinking, but there&#8217;s something happening and it&#8217;s not telling you what that&#8217;s happening. And so it&#8217;s really hard to know what to anticipate, which is the other reason why, my talk, my opinion, like you need to build guardrails around it, to force it into doing things and then make it so that it can&#8217;t escape.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t think anything that I was saying, or presenting or talking about is particularly unique, especially now. But the key thing that I found for me in my workflow was there needs to be a forcing function, needs to be some kind of a forcing function to make sure that it has to do the thing. It cannot complete the task without doing the stuff that you told it to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:53] <strong>Nathan Wrigley:</strong> So it&#8217;s literally like task police?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:55] <strong>Chris Reynolds:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:56] <strong>Nathan Wrigley:</strong> So, the idea is that whatever you ask it to do, it does it, but prior to giving you the final output, it runs through this project contract, as you call it. And hopefully that will then shepherd it in a certain way so that it&#8217;ll produce something which is adjacent to what you want to come out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:13] <strong>Chris Reynolds:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:14] <strong>Nathan Wrigley:</strong> Okay. So how does that work? Where does this project contract live? How do you in, I&#8217;m guessing English in your case, how is it that you write that in a way which is, you&#8217;re codifying everything, you make sure that all the T&#8217;s are crossed and the I&#8217;s are dotted. Just run us through the process of producing a project contract. And obviously, the nature of the topic itself would I&#8217;m sure define that, but just give us some rough ideas.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:40] <strong>Chris Reynolds:</strong> There&#8217;s a lot of markdown files. Fundamentally, like Claude is supposed to read, at the beginning of each new session, the contents of a Claude.md file that is in the project directory. Wherever you&#8217;re running Claude, you can give it a Claude.md and it will, that will give it an understanding of whatever, how it should interact with this project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Within that and beyond that, you can have a bunch of other different files. You can tell it about, you have a docs folder and you have more documentation there. There&#8217;s also an agents.md file, which you can use in various different ways. It&#8217;s another sort of markdown file that&#8217;s only for agents.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, in my case, what I was talking about, is there&#8217;s a reviewer agent. So it&#8217;s specifically like you talk to Claude Code, you say build this thing, and then after it&#8217;s done building the thing, a reviewer agent is spawned to check the work of the first agent. Make sure that it did a whole bunch of stuff, and then if it didn&#8217;t reject the code.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so there&#8217;s a bunch of files in my repository that are about how the reviewer agent works so that Claude understands what to expect. And then there is a checklist that has, these are the specific line items that I want every single commit to pass before this is an acceptable commit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it&#8217;s the whole gamut of everything, right? It&#8217;s like, does the build pass? Does linting pass? Does the test pass? There&#8217;s accessibility pass? All these things. Did you accidentally, or intentionally, commit like secrets to the repository? Stuff like that. It needs to go through this whole checklist. And then, if it passes, it writes a file to the file system that says, okay, approved. And this is the timestamp. And then that allows, if that file exists and the timestamp is valid, then Claude can actually make a commit, and it will actually commit the code. If it does not have that file or the timestamp is too old, then it will be rejected.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I have this hooked into a pre-commit hook. So if it doesn&#8217;t trigger the reviewer agent on its own, if I tell it to commit the code, it&#8217;s going to hit that gate, and force the reviewer agent to spawn. So it can&#8217;t get around it. And that&#8217;s the forcing function.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A couple people are asking about other workflows and whatever, and how to do it in different environments where maybe you&#8217;re not using a Git repository or something. And, the key is to find a forcing function. Find something that can&#8217;t actually weasel its way out of it, because it&#8217;s going to try to weasel its way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I had to write in a bypass for me to personally be able to commit code, because otherwise it&#8217;s going to ask for the reviewer agent. And it will try to use that bypass that I wrote for me because again it&#8217;s an unruly child. So it&#8217;s going to try to do that thing and, then you yell at it and tell it not to do that, and it says, oh, I&#8217;m very sorry.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s going to try to find these loopholes and circumvent everything that you&#8217;re trying to do. So the way that you force it to do all the stuff in this long checklist that I have is by creating something that it just can&#8217;t get around.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:27] <strong>Nathan Wrigley:</strong> So I can imagine that the people listening to this, the sort of AI doomers saying, &#8220;But Chris, it&#8217;s just AI all the way down. You&#8217;ve got AI checking AI.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:34] <strong>Chris Reynolds:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:35] <strong>Nathan Wrigley:</strong> Which on the face of it seems really peculiar. And also the fact that the guardrail is at the end of the process as opposed to, you would kind of hope that it would get it right at the beginning, but then you might just have to reject whole things based upon it. And then the fact that it sounds like from what you were saying, as if AI has almost like a predilection to misbehave.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:57] <strong>Chris Reynolds:</strong> I assume it has a predilection to misbehave.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:59] <strong>Nathan Wrigley:</strong> But does it feel like that? Is this predictability to, if I don&#8217;t put the guardrails and I don&#8217;t put this sort of corralling function in, what I&#8217;m going to get out is just going to be aberrant and useless and just who knows what&#8217;s going to come out?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:12] <strong>Chris Reynolds:</strong> I think that&#8217;s a little bit extreme. I said that I assume that it&#8217;s going to misbehave because if you don&#8217;t assume. Basically if you don&#8217;t prepare for the worst, it&#8217;s going to bite you in the ass.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:21] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:22] <strong>Chris Reynolds:</strong> So you have to assume. And one of the things I&#8217;m sure that people who are listening who have used LLM coding tools specifically, will be able to relate to, is oftentimes, this is one of the first discoveries that I had when I started using this stuff. You ask it to build a thing and it builds that thing, but there&#8217;s one thing wrong with it. So you ask it to fix that one thing and it refactors the entire thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And in the course of refactoring the entire thing, it lost some other thing that was there before that you liked that you want to have back. And so you tell it to bring that back and it rewrites the whole thing again, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">That&#8217;s how it works, because a lot of times it&#8217;s not able to like even retain the actual memory of the original state. So it just writes things from scratch every single time. Which from a human perspective is like bonkers, right? But from a computer standpoint, it&#8217;s oh this is a new interaction, so I&#8217;m doing this fresh.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the way that you solve for that problem is okay, if I force you to write tests for every single thing you&#8217;re doing, then you can&#8217;t go and revert a bunch of stuff or refactor stuff without those tests failing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:31] <strong>Nathan Wrigley:</strong> Right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:32] <strong>Chris Reynolds:</strong> And again, starting to like build things around it to force it into a shape so that it&#8217;s actually the thing that is closer to what you want. What I&#8217;m hearing is anxiety about the uncertainty that non-determinism, the like chaos, you never know, I don&#8217;t know. It doesn&#8217;t bother me. And I don&#8217;t know if that&#8217;s a character flaw of mine that it doesn&#8217;t bother me, as much. Or if it&#8217;s just like being comfortable with the chaos, but also understanding the chaos enough to know what to expect.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because the other thing I think that we&#8217;re seeing right now, in this moment in August of 2026, in Phoenix, Arizona, is that a lot of people are looking at this stuff for the very first time. A lot of people are just now coming to Claude Code, or have only started using it in the last couple months because it got really good around like November, December last year. Like, all of a sudden they did an update and it was just phenomenal, and it was able to do way more. And not just Claude, but like all the LLMs, they got really good at code. All of a sudden, and so now it&#8217;s a big thing, and so now more people are using it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I&#8217;ve been playing with LLMs since the very first Chat GPT model. I say that because there&#8217;s a lot of stuff that I learned over the course of the process, and I wasn&#8217;t using it for work necessarily. I was just using it for play and for, Dungeons and Dragons and whatever. But a lot of those things that I learned over the course of using it in those contexts, those non-work contexts, led me to understand the limitations, and where it falls down, and where it does well and the things to expect. So that when we got to this point, I already had an understanding of this is how it works, so these are the things I need to be looking for.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:15] <strong>Nathan Wrigley:</strong> Yeah. So that&#8217;s really curious. So the history that you have with it has given you a real deep understanding of what the expectations are for &#8220;Okay, this is typically where it doesn&#8217;t perform well or these are the things that it typically can do well.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:26] <strong>Chris Reynolds:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:27] <strong>Nathan Wrigley:</strong> Okay. So with your guardrails built in, so we&#8217;ve got your project contract that you buried inside the project somewhere, and it&#8217;s doing all these checks and balances. Where does that take you in terms of confidence?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t know if you want to put a number on that, like a percentage. How does it take you from zero to 99% confident in what&#8217;s coming out? Is it more like 80%? Is human review needed in every single circumstance, or. Just run us by the confidence that you get from producing that document?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:54] <strong>Chris Reynolds:</strong> I don&#8217;t review line by line the code that AI produces.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:01] <strong>Nathan Wrigley:</strong> Just curiously, at what point in the calendar did that moment occur where you suddenly said to yourself, you know what, there&#8217;s just no, I&#8217;m just reading everything and everything&#8217;s great. There&#8217;s just no point in me checking everything now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:13] <strong>Chris Reynolds:</strong> I mean, probably way earlier than it should have, if I&#8217;m honest. Yeah, I don&#8217;t, and one of the arguments that I&#8217;ve actually heard some of the engineers that I work with, at Pantheon, say is the fact that no one is actually reading all of that code generated by Claude or whatever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, his argument is like, basically no one&#8217;s going to do that because it&#8217;s so much, and it&#8217;s here and whatever. So you can say that you&#8217;re doing it, but you&#8217;re probably not. And if you say that you&#8217;re doing it and you&#8217;re not, you&#8217;re just lying to yourself. So it&#8217;s better to be honest and be like, yeah, no, I don&#8217;t actually, than to pretend like that&#8217;s not the case. So I don&#8217;t actually review a lot. And not like intentionally, like I will look at it. The demo, I gave a live demo yesterday, which is exciting because it&#8217;s a non-deterministic thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:02] <strong>Nathan Wrigley:</strong> Oh yeah. Good luck.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:04] <strong>Chris Reynolds:</strong> But what was interesting about that is because the scope of the task was very small. It was like, there&#8217;s a horizontal bar on mobile devices on this specific page on my site. Very specific thing. And I, when I practised it, half a dozen times or more, it got to the same conclusion every single time. When I demoed it yesterday, it got to the same conclusion.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I can look at the code and okay, there&#8217;s the tests. I&#8217;m not going to read the test and how it wrote the test, but I can see what the change in is. It is just adding a class to a div. And it pretty much was the same class to the div every single time. So like, I can review that and be pretty confident with that. That&#8217;s a hundred percent confidence.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Also extremely small change, but that&#8217;s also at the end of yeah, it went through the 45 point checklist. It did all of the things. It wrote the accessibility, it did the, like everything is following these rules. And because I have all of these rules, and because I&#8217;m fairly confident that it&#8217;s actually going through that list, that also makes me feel like, okay, I can be a little bit, it&#8217;s a little bit more trustworthy, when it produces this output, then it was before it had all that stuff in place.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:10] <strong>Nathan Wrigley:</strong> Yeah. So in my head, there was a period of time where I didn&#8217;t trust that if I said to my son, what&#8217;s three add seven, that 10 would come out. And then there was a moment where I don&#8217;t need to ask him that question anymore. I have complete confidence that if I were to ask him that question, he would say 10.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:26] <strong>Chris Reynolds:</strong> Sure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:26] <strong>Nathan Wrigley:</strong> And it would be 10 every single time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:28] <strong>Chris Reynolds:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:28] <strong>Nathan Wrigley:</strong> And it I think, I feel like it&#8217;s a bit like that. Over time you&#8217;ve just grown accustomed to, it can do this kind of thing. I now trust it in that sphere. Does that sort of sum it up? You, personally, you have built up that level of trust, but it wouldn&#8217;t necessarily be the same for me if I started my journey. I would have to go through the building up of trust in the same way that you did.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:49] <strong>Chris Reynolds:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:49] <strong>Nathan Wrigley:</strong> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:49] <strong>Chris Reynolds:</strong> But I do think that, like the reviewer workflow that I built can help you get there. Because if you put that into your project, and customise your list of, your checklist for all the things that you want to have running on everything that you are running. The goal is to make it more trustworthy, and to make it more do the thing that you expect and wanted to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:10] <strong>Nathan Wrigley:</strong> Could you just tell us some of the things that are in that document? So I think you said 45 and maybe that&#8217;s subject to change. Maybe next week it&#8217;ll be 49 or what have you. And maybe some of the more curious ones that wouldn&#8217;t necessarily drop out. I can imagine that you would ask it to do certain things, de rigueur, every time that, but some of the more curious ones, perhaps ones that you&#8217;ve come up with lately that our listeners might think, oh, okay. I&#8217;ve never thought of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:31] <strong>Chris Reynolds:</strong> I have it use test driven development or I tell it to use test driven development. And the reason for that. So test driven development is when you write the test and then you write the code to pass the test.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it turns out that AI can do this far better than humans, because humans don&#8217;t want to do this, because it&#8217;s like, it breaks your brain. But an AI can do it, and if an AI can do it, then I&#8217;ll let the AI do it. And by having the AI write the test that the code needs to pass in order to accomplish the task that you&#8217;re asking it to do first, then that means A, again, you&#8217;re never going to have regressions, because the test is already there. And B, it already knows how to fix the thing, because it wrote the test to make the thing fail. So that&#8217;s a sort of a important nuance, in there, that isn&#8217;t necessarily, like you can write unit tests, whatever, but starting with the test is really valuable.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s a couple things that I have in the checklist specifically. The big one, I think that is maybe curious is making sure that it doesn&#8217;t write secrets to the file system.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:33] <strong>Nathan Wrigley:</strong> Even saying that out loud is so peculiar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:36] <strong>Chris Reynolds:</strong> Because it will do that. And the reason why that rule has to exist is because there was a point in time when that rule didn&#8217;t exist and then it wrote this. And that&#8217;s even like secrets in, WordPress has a weird concept of what a secret is anyway, because we have API keys in our wp-config files and stuff like that. And theoretically we shouldn&#8217;t be doing that either. But we don&#8217;t have a really good universal form of like, secrets management. So it gets wibbly wobbly. But yeah, so not writing secrets to the file system is pretty important.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, honestly it&#8217;s really, it&#8217;s not super wild stuff. It&#8217;s like making sure tests pass, making sure you have accessibility checks. I guess one thing that is maybe unique So I designed this site with Claude too. Which is also an experiment because it&#8217;s like, I have no idea how AI is going to approach design. And so one of the things, I know like at my workplace, we use Storybook, for our design system. And I thought, that seems like a good tool. Maybe I can have AI build a Storybook.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so I basically built this system so that it will, when I want it to build a new component, it builds the component in Storybook so that I can review the design first, and go back and forth there, and then implement the component into the thing. So there&#8217;s stuff in there about, if you&#8217;re introducing any new design component, then it has to be done in Storybook first.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:56] <strong>Nathan Wrigley:</strong> Okay. Yeah. Yeah. That, some interesting stuff in there, but I guess everybody&#8217;s going to have a sort of different file.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:02] <strong>Chris Reynolds:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:02] <strong>Nathan Wrigley:</strong> Okay. So I wonder if you have any intuitions as to the process that you&#8217;ve just described and that you&#8217;ve gone through, August, 2026. Do you have an intuition that in the next few years, this kind of thing, the AI companies will solve this problem, that it will become more truthy by default? Or do you see it, that this is a thing that we&#8217;re going to have to wrestle with from now on? That our systems, our AIs, there&#8217;s always going to be this strange tendency to hallucinate, to make things up, just to go off the rails and do peculiar things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now obviously I&#8217;m asking you to stare into a crystal ball, but I do wonder if there has been a more truthful output over time, or if it&#8217;s just getting wilder and wilder.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:42] <strong>Chris Reynolds:</strong> I think that what we will see more of is more integrated like agent orchestration. So what I&#8217;m doing is essentially like a form of agent orchestration. I&#8217;ve got one agent doing the one thing, I&#8217;ve got another agent that reviews the work of the first thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And even like the keynote yesterday, she was talking about a not very dissimilar process, where like there&#8217;s five different agents and reviewer was one of them. There&#8217;s like a planner, there&#8217;s a coder, there&#8217;s a whatever. And I think that is a thing that we&#8217;ll probably start to see more of and then maybe at some point. when you talk to Claude, when you write a prompt into Claude, you&#8217;re talking to a thing. But underneath the hood, in the black box of Claude&#8217;s brain, there&#8217;s actually five different agents that are running concurrently that are processing this thing and doing their different tasks or whatever. So when it&#8217;s thinking, then it&#8217;s doing five different, like it&#8217;s going through that process. I think maybe that&#8217;s the thing that might happen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:40] <strong>Nathan Wrigley:</strong> I&#8217;m just so fascinated by how, by now the year 2026, we&#8217;ve just all accepted that this is how it is. But if you could put 2021 Chris in that chair, you are sat over there somewhere listening to you talk, you&#8217;d be, &#8220;No, this is Star Trek. This is literal science fiction. I haven&#8217;t the faintest idea of what he&#8217;s talking about. None of this adds up, computers can&#8217;t do that. They&#8217;ll never do that.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">And yet here we are, we kind of blew through the Turing Test, like it was nothing. And that felt for the longest time, like that was going to be an important milestone. And everybody checked their watches like, &#8220;Oh goodness, that happened.&#8221; It is remarkable how quickly the landscape is changing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:17] <strong>Chris Reynolds:</strong> What&#8217;s really interesting is one of the first people that I read about AI stuff, she&#8217;s an AI researcher, and she specifically focuses on small language models like the very old models that existed before GPT and whatever. And fundamentally how these things all work is very very similar. But like back, so this is getting into 2021, 2022 era of stuff, where like, it exists but it&#8217;s really bad. I don&#8217;t know how many people still remember, Horse eBooks, the Twitter account.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:49] <strong>Nathan Wrigley:</strong> No.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:50] <strong>Chris Reynolds:</strong> But it was like this bizarre account, that was a bot account, that was just like an AI or machine learning or something, some robot just like spitting garbage into Twitter, that just made no sense at all. And was, it&#8217;s, hilarious. And you also remember, in the not terribly distant past, when we would get like, weird phishing emails, but it would have different tone changes in voice. Like it was very, obviously written by a robot or like spam messages and stuff like that. And that was just what existed at the time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">None of the things that exist today are like, they all come from the same root, but for sure, the flip from this is garbage, to this is genuinely useful, or at least sounds humanlike, was it, felt like overnight. And it felt like a wild flip. When Chat GPT first became available for the public, that was how is this even? And also like there is the whole thing, very shortly after that when Microsoft released the Bing Chat bot.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:53] <strong>Nathan Wrigley:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:53] <strong>Chris Reynolds:</strong> There was the whole thing about like Bing wanting to marry this reporter. And that goes to show how little we even know about the things that we&#8217;re building. Like, none of the AI companies really understood, or even still I think understand? Why it works the way it does.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:11] <strong>Nathan Wrigley:</strong> That&#8217;s quite an alarming admission actually.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:13] <strong>Chris Reynolds:</strong> It&#8217;s just, it does.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:14] <strong>Nathan Wrigley:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:14] <strong>Chris Reynolds:</strong> So we&#8217;re just going to keep going. Which is also, I find that alarming from the perspective of, now they&#8217;re asking for like huge new data centres across everywhere. I&#8217;m sure anybody listening to this is angry about data centres, and I&#8217;m angry about data centres. But like, that&#8217;s with the belief that those data centres are going to matter meaningfully. And I don&#8217;t know if they will.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Like we don&#8217;t, because we didn&#8217;t know how we got here. And it&#8217;s doing the thing now. I can use it to code my site. Like I can do that today. Do I need 50 new data centres across the United States to make that better? I don&#8217;t know.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:55] <strong>Nathan Wrigley:</strong> You&#8217;ve almost described the perfect dystopian science fiction plot there, haven&#8217;t you in a way? This stuff just all happened. It gave a really beguiling approximating humanlike responses that got more human over time to the point where we couldn&#8217;t.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:08] <strong>Chris Reynolds:</strong> Did we just invent Skynet?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:09] <strong>Nathan Wrigley:</strong> Yeah. We, can&#8217;t detect that it&#8217;s not a human anymore. It really does feel like, somewhere hidden from our view is an evil overlord stroking a cat or something like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And of course, we don&#8217;t really know how we got here, but I am so beguiled by it. I&#8217;ve got the same concerns as you. Data centres, the environment, all of this wasting of the Earth&#8217;s resources. But at the same time, that doesn&#8217;t seem to stop me from being curious about it and trying it out and the AI is just wrong for everybody else to use. But when I use it, oh, it&#8217;s perfectly fine. But, you know? That&#8217;s a thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:41] <strong>Chris Reynolds:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:42] <strong>Nathan Wrigley:</strong> Okay. I think we&#8217;ll knock it on the head there, as we say in the UK. Is there anything you wish that we had covered just before we end it? Or do you think we got through most of what we needed to.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:50] <strong>Chris Reynolds:</strong> I think one of the things that gives me pause or concerns me most about AI, is the sort of like handing over that amount, or an amount or any amount, of sort of cognitive load to AI. And therefore just letting those parts of our own selves, and our own brains like dwindle and wither.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think about this from the perspective of just me personally, my kids, my family, whatever using it and then like becoming less skilled ourselves. But I also think about it from the perspective of, if we&#8217;re in engineering, in development, in the world that we are working in. If we are telling everyone, &#8220;oh your job now is to be essentially a senior engineer reviewing the work of a junior developer, that is the AI,&#8221; how do senior developers exist?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:41] <strong>Nathan Wrigley:</strong> You&#8217;ve removed that bottom rung of the ladder, haven&#8217;t you? Yeah. You&#8217;ve taken away the capacity for somebody coming out of college to go on the first step. And then the second and then the third. Because the AI did all the first, second and third step.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:52] <strong>Chris Reynolds:</strong> Like I understand that there&#8217;s a different set of skills, and a different set of rules and whatever, things that are going to be part of your job, to be that reviewer, to be that new engineer that uses AI to be the developer. But there&#8217;s certain things I think, that are part of that learning journey that got me to where I am, that got other senior developers to where they are, to understand the context, to be able to guide the AI that I don&#8217;t know that you can circumvent that. I don&#8217;t know that you can bypass that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:41:22] <strong>Nathan Wrigley:</strong> I think you&#8217;d be curious if the AI company&#8217;s employed like a really credible team of philosophers. You know what I mean? Like for every a hundred developers, we have 10 philosophers, who are just going to think and worry about what the heck&#8217;s going on. It sounds ridiculous, but maybe that&#8217;s what we need because, some of the things that you&#8217;ve described today, they&#8217;re just so curious that you need to shepherd it, you need to constrain it, you need to worry about the bizarre things that it can get up to. We need to worry about the future, the data centres and all of this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, on some level it does feel a bit like we&#8217;ve got a blindfold on. We appear in our own minds at least we appear to be going in the direction that we want to go in. But I don&#8217;t know, I guess only time will tell. If we&#8217;re all here in 2027.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:05] <strong>Chris Reynolds:</strong> That will be the thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:05] <strong>Nathan Wrigley:</strong> Then we succeed 2029, who knows? All bets are offs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:09] <strong>Chris Reynolds:</strong> Yeah. I can count three years in the future that my job is probably not going to go away. But beyond after that, beyond that, I don&#8217;t know.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:15] <strong>Nathan Wrigley:</strong> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:16] <strong>Chris Reynolds:</strong> I&#8217;m pretty sure, I&#8217;m pretty sure my job is okay because I do think, developer relations at all about talking to humans, but maybe there&#8217;s not going to be any humans to talk to, so maybe I&#8217;ll just be talking to AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:24] <strong>Nathan Wrigley:</strong> Okay. WordCamp US 2029. It&#8217;s a date. We&#8217;ll be back at that point.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris Reynolds, thank you for sharing all of those thoughts and, yeah, that&#8217;s been really educational. Thank you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:34] <strong>Chris Reynolds:</strong> Thank you for having me.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have Chris Reynolds.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris has been immersed in the WordPress world for around 20 years, with a career spanning agency work and now leading the developer relations team at Pantheon. His deep WordPress experience is paired with a playful approach to emerging tech, making him a familiar voice at events like WordCamp US and across the wider community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In today’s episode, the discussion explored the fast-changing landscape of AI-assisted development, getting into how large language models, like Claude, are not only changing the way developers build for the web, but also how they’re collaborating with these tools while mitigating risks. Chris shares insights from his recent talk at WordCamp US, “Parenting Claude: Guardrails for AI-Assisted Development,” where he introduces the concept of a “project contract”, essentially a structured set of rules and checklists built directly into the coding workflow to ensure AI-generated code meets standards for testing, accessibility, security, and design.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We discussed the newfound playfulness in web development. Chris makes the case that, thanks to AI, the traditional barriers to entry are eroding, enabling even those without a formal developer background to build and experiment much more easily. At the same time we need to be mindful of the importance of establishing robust guardrails, like automated reviewer agents and pre-commit hooks, so the AI doesn’t take shortcuts, or accidentally introduce chaos, or secrets, into your codebase.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation focused not only on technical solutions but also got into bigger questions about trust, how much oversight AI really needs, and the evolving role of developers. Chris emphasised that while these AI tools can accelerate and democratise coding, they can also pose a challenge to conventional wisdom around code review and software reliability. So these new frontiers are both exciting and a cause of anxiety for developers who can sense the industry move from the deterministic, step-by-step processes, to the unpredictable, and occasionally wild, world of non-deterministic AI models.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re interested in how AI is transforming web development, from practical workflows to philosophical ramifications, and how you can implement AI without losing control of your projects, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Just before we begin, the manner in which this episode was recorded was not my usual process, and so the audio is not quite as good as I’d deliver.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://pantheon.io\"> Pantheon</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.linkedin.com/in/chrissreynolds/\">Chris on LinkedIn</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris&#8217; presentation at WordCamp US 2026 &#8211; <a href=\"https://us.wordcamp.org/2026/session/parenting-claude-guardrails-for-ai-assisted-development/\">Parenting Claude: Guardrails for AI-Assisted Development</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://next.jazzsequence.com\">Chris&#8217; website</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 10 Sep 2026 10:24:58 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:30;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:22:\"Matt: Scanning Plugins\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=154706\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:39:\"https://ma.tt/2026/09/scanning-plugins/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:216:\"<p class=\"wp-block-paragraph\"><a href=\"https://make.wordpress.org/plugins/2026/09/09/automated-security-review-for-plugin-releases/\">It&#8217;s a really big deal that we&#8217;re scanning all the plugins now</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 10 Sep 2026 10:18:07 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:31;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"Open Channels FM: Gold Eagle, AI Crawlers, and California Lawmakers Shake Up Open Source Security and Infrastructure\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561506\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:121:\"https://openchannels.fm/gold-eagle-ai-crawlers-and-california-lawmakers-shake-up-open-source-security-and-infrastructure/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"Legal and technical systems struggle to keep pace with AI and open source development.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 10 Sep 2026 09:25:31 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:32;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"Open Channels FM: Changelog v5.0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561497\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:39:\"https://openchannels.fm/changelog-v5-0/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"Changelog updated for version 5.0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 10 Sep 2026 09:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:33;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:89:\"Open Channels FM: Major Updates with Version 5.0 and New Developments at Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561471\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:96:\"https://openchannels.fm/major-updates-with-version-5-0-and-new-developments-at-open-channels-fm/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:172:\"Open Channels FM launched version 5.0, featuring new shows, enhanced navigation, and updated content focus, shifting toward open source philosophy and community engagement.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 09 Sep 2026 12:28:19 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:34;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"HeroPress: How a Law Student Ended up with WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://heropress.com/?post_type=heropress-essays&p=8837\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:156:\"https://heropress.com/essays/how-a-law-student-ended-up-with-wordpress/#utm_source=rss&utm_medium=rss&utm_campaign=how-a-law-student-ended-up-with-wordpress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:23022:\"<img alt=\"Pull Quote: We often mistake not seeing a path for being lost.\" class=\"attachment-large size-large wp-post-image\" height=\"512\" src=\"https://heropress.com/wp-content/uploads/3026/09/astha_jain_banner.webp\" width=\"1024\" /><figure class=\"wp-block-audio\"><audio controls=\"controls\" src=\"https://heropress.com/wp-content/uploads/3026/09/astha_jain_heropress.mp3\"></audio><figcaption class=\"wp-element-caption\">Hear Astha read her own essay aloud.</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">I come from a transitional generation, and somehow, I’ve ended up as a hard core non-tech person in a heavily tech-driven space. Fitting into a box has never really been my thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And perhaps, that has been the point.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-how-often-do-you-think-you-re-lost\"><strong>How often do you think you’re lost?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">We often mistake not seeing a path for being lost.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We grow up believing that a meaningful life comes with a roadmap: choose a direction, follow it, and eventually arrive somewhere. But what happens when you can&#8217;t see the road ahead?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sometimes, the path doesn&#8217;t exist yet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My own journey has rarely looked linear. I started blogging on WordPress at 16 because I wanted somewhere to put my thoughts and my poetry. I studied law, organised events alongside it, and while pursuing my passion for public speaking, discovered my love for community building.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And eventually, through a rather topsy-turvy turn of events, I found myself turning my legal background into entrepreneurship.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Astha holding a microphone and gesturing with one hand.\" class=\"wp-image-8839\" height=\"576\" src=\"https://heropress.com/wp-content/uploads/3026/09/image1-1024x576.webp\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">Astha giving opening remarks at EmpowerWP </figcaption></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Astha in a long dark sari, standing in front of a wall with a timeline of WordPress on it, at WordCamp Asia in Philippines.\" class=\"wp-image-8868\" height=\"1406\" src=\"https://heropress.com/wp-content/uploads/2026/09/image2-edited.webp\" width=\"1999\" /><button class=\"lightbox-trigger\" type=\"button\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">Astha in a saree at WCAsia &#8217;25</figcaption></figure>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">From the outside, these may look like a lot of deviations. Even to me, there were moments when the future looked bleak and hazy. I wondered whether I was falling behind while people around me seemed to have “figured it out,” found their direction, and were already excelling.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I found myself feeling lost.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-regaining-control-by-finding-a-pattern\"><strong>Regaining control by finding a pattern</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">But looking back, and eventually connecting the dots, I realised there <em>was</em> a constant. A pattern I kept coming back to: <strong>people, ideas, purpose, and the desire to contribute.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The mediums kept changing. The underlying pull did not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that&#8217;s when it hit me:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Sometimes, not fitting into the box isn&#8217;t the problem. Rather, it is the answer.</strong></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-who-am-i-and-where-it-all-started\"><strong>Who am I and where it all started</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">So, let me start again.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My name is Astha, and I discovered the WordPress community back in 2023.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I was a law student who happened to stumble upon a WordPress anniversary meetup, where conversations were already underway about WordCamp Bhopal happening again after quite a while.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I started as an organiser, partly because of the sheer joy of doing what the job demanded— the knack for managing things… and people.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We had two broad purposes: reignite the WordPress ecosystem in town and show attendees a glimpse of Bhopal in the best possible way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then, WordCamp Bhopal happened.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\"><em>WordCamp Bhopal felt like a family reunion, except that you’re meeting those people for the very first time.</em></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Read my</em> <a href=\"https://asthajain.in/wordcamp-bhopal-2023-conference-in-city-of-lakes/\"><em>experience as an Organiser at my first ever WordCamp</em></a> <em>| WordCamp Bhopal 2023</em></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-what-next-after-organizing-the-first-wordcamp\"><strong>What next after organizing the first WordCamp?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">I had an incredible time, but also, I had no intentions of dwelling any further.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But credit to the people I met here— WordCamp Mumbai happened. </p>\n\n\n\n<p class=\"wp-block-paragraph\">And somewhere between Bhopal and Mumbai, something shifted.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Astha&apos;s thank you trophy for being Speaker at WordCamp Mumbai 2023 \" class=\"wp-image-8848\" height=\"1024\" src=\"https://heropress.com/wp-content/uploads/3026/09/image4-772x1024.webp\" width=\"772\" /><button class=\"lightbox-trigger\" type=\"button\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">Memento by WCMumbai </figcaption></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Celebration cake for 22nd anniversary of WordPress by WordPress Bhopal community.\" class=\"wp-image-8846\" height=\"1024\" src=\"https://heropress.com/wp-content/uploads/3026/09/image3-1024x1024.webp\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">WP22 anniversary cake</figcaption></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://heropress.com/wp-content/uploads/3026/09/Memento-WCPokhara.webp\"><img alt=\"\" class=\"wp-image-8873\" height=\"1783\" src=\"https://heropress.com/wp-content/uploads/2026/09/Memento-WCPokhara-edited.webp\" width=\"1607\" /></a><figcaption class=\"wp-element-caption\">Memento by WCPokhara</figcaption></figure>\n</div>\n</div>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Family photo from WordCamp Bhopal 2023\" class=\"wp-image-8852\" height=\"681\" src=\"https://heropress.com/wp-content/uploads/3026/09/image8-1024x681.webp\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">Family photo from WordCamp Bhopal 2023</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The fire these two events ignited in me was insane. By 2024, I found myself thinking much more consciously about the gap I saw between my own field and the technology ecosystem, and between technology and the larger society around us.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I started looking for ways to bridge those gaps wherever I could.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I began seeing community events differently.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Not just as events. </p>\n\n\n\n<p class=\"wp-block-paragraph\">But as opportunities to bring people together around something that could potentially make a difference.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>I think community events are a great way— a stage from where you could bring a change. It&#8217;s an opening for you to utilize, to serve a purpose.</em></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-outsider-to-builder\"><strong>Outsider to Builder</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">I was supposed to be an outsider. I <em>was</em> one.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the cordial, welcoming, “just a smile away” setup of this community had me, for good.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think the give-and-take in my case sums up as <strong>perspective</strong>.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-witnessing-grandeur-of-the-og-camp\"><strong>Witnessing grandeur of the OG Camp</strong> </h2>\n\n\n\n<p class=\"wp-block-paragraph\">And then came the ultimate, Crown of Jewels, Camp of Camps: <strong>WordCamp Asia.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">I had an opportunity to emcee at WCAsia. Absolutely loved the energy. That&#8217;s probably the least I can say, because words still don&#8217;t quite justify how I felt at that moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Exposure is so important— culturally, professionally, and in all the other ways possible. For me, WordCamp Asia was exactly that. </p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\"><em>Some people knew of my presence there. A majority did not. The people I knew helped me connect with the people I didn&#8217;t. But there were also those who came by without knowing me at all— just a smile or a kind word away.</em></p>\n</blockquote>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Emcees at WordCamp Asia 2025\" class=\"wp-image-8849\" height=\"768\" src=\"https://heropress.com/wp-content/uploads/3026/09/image5-1024x768.webp\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">Emcees at WordCamp Asia 2025</figcaption></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full wp-lightbox-container\"><img alt=\"WPBesties Winner photo featuring Taco, Astha, Anooja, Michelle, Nathan &amp; Lokesh.\" class=\"wp-image-8853\" height=\"1014\" src=\"https://heropress.com/wp-content/uploads/3026/09/image9.webp\" width=\"1020\" /><button class=\"lightbox-trigger\" type=\"button\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">WPBesties winner image feat. Taco, Astha, Anooja, Michelle, Nathan &amp; Lokesh</figcaption></figure>\n</div>\n</div>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://heropress.com/wp-content/uploads/3026/09/Indian-contingent-at-WCAsia.webp\"><img alt=\"\" class=\"wp-image-8871\" height=\"683\" src=\"https://heropress.com/wp-content/uploads/3026/09/Indian-contingent-at-WCAsia-1024x683.webp\" title=\"Indian Contingent at WCAsia 2025\" width=\"1024\" /></a><figcaption class=\"wp-element-caption\">Indian contingent at WordCamp Asia 2025</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://asthajain.in/wordcamp-asia-2025-recap-best-conference/\">I can’t seem to get over from WordCamp Asia</a>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">It reminded me, once again, how simple yet profound human connections can be.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I came back apart from a sore throat, with a rejuvenated sense of self, and perhaps a little more courage… which led me to lead <strong>EmpowerWP Bhopal 2025</strong>.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-shifting-focus-from-what-why-empowerwp-bhopal\"><strong>Shifting focus from</strong> <strong><em>What</em></strong> <strong>→</strong> <strong><em>Why</em></strong> <strong>: EmpowerWP Bhopal</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">This time, the question wasn&#8217;t simply <em>what event can we organise?</em> It was <em>who are we organising it for?</em></p>\n\n\n\n<p class=\"wp-block-paragraph\">This was the time when Women In WordPress were organising women’s day event across the globe. We wanted to bring women in Bhopal into the conversation who weren&#8217;t necessarily already part of the ecosystem— homemakers, women looking to upskill, women on career breaks, small business owners, and women who had, for one reason or another, found themselves somewhere outside the active workforce.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When we envisioned EmpowerWP Bhopal, we knew it had to be inclusive— not just for the conventional attendees, but also for the very women who have shaped our lives. Trying to make digital opportunities feel a little closer to home. It went beyond our expectations in the best possible way.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://heropress.com/wp-content/uploads/3026/09/image12.webp\"><img alt=\"Newspaper report featuring EmpowerWP Bhopal (Women&apos;s day event) in 2025\" class=\"wp-image-8856\" height=\"689\" src=\"https://heropress.com/wp-content/uploads/3026/09/image12.webp\" title=\"Newspaper cutting of EmpowerWP Bhopal\" width=\"1024\" /></a><figcaption class=\"wp-element-caption\">Newspaper report highlighting EmpowerWP (Women&#8217;s day event)</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://central.wordcamp.org/news/2025/04/empowerwp-bhopal-2025-a-journey-of-inclusion-and-impact/\">Read about EmpowerWP: A journey of Growth and Inclusion</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">And then came the <strong>WP Build Tour</strong>.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-touring-across-the-state-igniting-the-fire-amongst-students\"><strong>Touring across the State: Igniting the fire amongst students</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">If EmpowerWP was about creating a bridge for women, WP Build Tour took the idea of access beyond the city.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We went across Madhya Pradesh, our state with 55 districts but just one active WordPress chapter, reaching more than <strong>1,700 college students</strong> and helping them build their own websites in a day.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\"><em>WP Build Tour 2025 was never just about code or content. It was about confidence. About potential realised. About futures being built— one student, one website, one breakthrough at a time. </em></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">The idea was rooted in something I had been thinking about for a while— the gap between what the industry needs, what students are taught, and what students actually get an opportunity to <em>do</em>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So we took WordPress to them.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://heropress.com/wp-content/uploads/3026/09/image10.webp\"><img alt=\"Group photo from one of the stops of WP Build Tour 2025.\" class=\"wp-image-8854\" height=\"576\" src=\"https://heropress.com/wp-content/uploads/3026/09/image10-1024x576.webp\" title=\"Group photo from a tour: WP Build Tour 2025\" width=\"1024\" /></a><figcaption class=\"wp-element-caption\">Group photo at one of the stops of WP Build Tour</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://central.wordcamp.org/news/2025/10/bhopal-hosts-wp-build-tour-2025-empowering-1700-students-across-central-india/\">Bhopal Hosts WP Build Tour 2025: Empowering 1700+ Students Across Central India</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">The WordPress community had given me the space to try these things— to experiment, to bring in ideas that perhaps didn&#8217;t fit the conventional definition of a tech event, and to push boundaries.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And for that, I remain deeply grateful.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\"><em>Organising events is one thing, and adding purpose to them takes it to another level. For us in Bhopal, organising events has never been just about the “event.” It’s about going a step further and sparking change, no matter how small. </em></p>\n</blockquote>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-the-realisation-at-wc-pokhara\"><strong>The realisation at WC Pokhara</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Asia had felt like a peak, and I was quite happy simply soaking in its afterglow.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Then, out of nowhere, I heard whispers of <strong>WordCamp Pokhara</strong> happening in Nepal. And just like that, something stirred again.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I had no plans. But this one felt like it had plans for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There was another thought that kept ringing in my mind:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>When I&#8217;ve had the privilege of being on both sides– non tech in tech, why not support the people who are still somewhere in the middle?</strong> So I wanted to talk about what we can do for the community and also <a href=\"https://asthajain.in/how-wordpress-community-helps-you-attend-flagship-wordcamps-scholarships-grants-support-programs/\">how the community supports us</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Packed up and flew to Nepal. And what did I find? My <em>alter ego</em>, perhaps.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I didn&#8217;t go looking for a community this time. But by the end of it, I knew— <strong>I belong here.</strong></p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://heropress.com/wp-content/uploads/3026/09/image11.webp\"><img alt=\"Group photo from WordCamp Pokhara 2025\" class=\"wp-image-8855\" height=\"683\" src=\"https://heropress.com/wp-content/uploads/3026/09/image11-1024x683.webp\" title=\"Group photo: WC Pokhara 2025\" width=\"1024\" /></a><figcaption class=\"wp-element-caption\">Group photo from WordCamp Pokhara 2025</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://asthajain.in/pokhara-people-purpose-my-wordcamp-nepal-journey/\">Read about WCPokhara: People and Purpose</a></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-the-ultimate-the-calling-the-answer\"><strong>The Ultimate. The Calling. The Answer.</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Just made me realise how our calling is not always something we discover at the beginning. Sometimes, it is the urge that keeps bringing us back, again and again, even when we try to walk somewhere else.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And how a community can make that uncertain journey possible: giving us people who encourage us, opportunities we couldn&#8217;t have seen alone, and sometimes simply the reassurance that we are not the only ones without a map.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thanks to constant supporters in this journey including (but not limited to) <a href=\"https://theadityashah.com/\">Aditya</a> Shah, the <a href=\"https://in.linkedin.com/company/wordpress-bhopal\">WP Bhopal</a> community, the global WordPress Community at length, and <a href=\"https://yoast.com/about-us/community/\">Yoast</a>! From celebrating WordPress anniversaries together to honoring <strong>WP Bhopal’s decade long journey</strong>… It&#8217;s been worthwhile to grow along.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It got me friends, and somewhere along the way, it got me a <em>life</em>!</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://heropress.com/wp-content/uploads/3026/09/image13.webp\"><img alt=\"Peers turned Friends from WordPress Bhopal celebrating success of WordCamp Bhopal 2023!\" class=\"wp-image-8857\" height=\"534\" src=\"https://heropress.com/wp-content/uploads/3026/09/image13-1024x534.webp\" title=\"Friends aka team members celebrating success of WCBhopal 2023\" width=\"1024\" /></a><figcaption class=\"wp-element-caption\">Peers turned friends celebrating success of WordCamp Bhopal 2023</figcaption></figure>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-what-s-up-with-me-now\"><strong>What’s up with me now?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Now, I am a lawyer turned entrepreneur, in the tech space. Building <a href=\"https://ariham.com\">Ariham</a>, a people-first agency, with WordPress at its core.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And when I look back at the 16-year-old who simply wanted somewhere to put her thoughts and poetry, I realise I couldn&#8217;t have possibly mapped this journey out. I don&#8217;t think I was supposed to.</p>\n\n\n\n<p class=\"wp-block-paragraph\">To so many firsts… first time making a website for somebody else, to the first international trip to the Philippines, to first time being a speaker at a foreign land… the WordPress community has taken me places, and I am so excited to see what we’re gonna be up to next! </p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-a-lesson-i-would-like-to-pass-on\"><strong>A lesson I would like to pass on</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Maybe the unconventional path isn&#8217;t a lack of direction. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Maybe it&#8217;s a different way of finding direction.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Maybe your calling isn&#8217;t always something you recognise immediately.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Maybe it&#8217;s the thing that keeps pulling you back.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The idea you can&#8217;t let go of.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The work you keep returning to.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The thing that, even after you&#8217;ve tried to walk away, somehow finds its way back into your life.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because sometimes, the <em>road not taken</em> doesn&#8217;t look like a beautiful path waiting for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sometimes, it looks like there is no path at all.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Maybe you&#8217;re not lost. Maybe you&#8217;re early. Or maybe you are the one building the road.</strong></p>\n<p>The post <a href=\"https://heropress.com/essays/how-a-law-student-ended-up-with-wordpress/\">How a Law Student Ended up with WordPress</a> appeared first on <a href=\"https://heropress.com\">HeroPress</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 09 Sep 2026 10:17:13 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Astha Jain\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:35;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"WordPress.org blog: Students Built 108 Websites in Two Weeks in Bangladesh\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21627\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://wordpress.org/news/2026/09/108-student-websites/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:9968:\"<p class=\"wp-block-paragraph\">In July, students at two campuses in Kishoreganj, Bangladesh, built 108 websites. In eastern Uganda, a workshop that arrived to find no electricity at the school ran anyway, for more than 100 learners, because a former student had asked for it. In Costa Rica, three university students taught a three-session WordPress class to 40 high schoolers, then wrote down exactly how they did it so anyone else could run the same class. None of these students paid to take part, and most had never built a website before.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Those workshops came out of two programs. WordPress Campus Connect brings free, hands-on WordPress sessions to schools and universities, run by local volunteers working from a shared curriculum. WordPress Credits goes further, placing students in mentored internships where they contribute to WordPress itself and earn academic credit for the work. Credits passed 226 graduates in July, up from 199 in June, and now works with 38 partner institutions across 16 countries.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What the Students Built</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The Kishoreganj series was organized by <a href=\"https://profiles.wordpress.org/devmuhib/\">Muhibul Haque</a>, who brought Campus Connect to two institutions two weeks apart. Students at <a href=\"https://events.wordpress.org/campusconnect/2026/kishoreganj/\">Kishoreganj University</a> built 38 sites in the first session. At Kishoreganj Polytechnic Institute, where guest speaker <a href=\"https://profiles.wordpress.org/shiponkarmakar/\">Shipon Karmakar</a> traveled more than 80 kilometers to attend, they built nearly 70 more. The <a href=\"https://events.wordpress.org/campusconnect/2026/kishoreganj/success-stories/\">success stories page</a> for the series counts more than 150 participating students so far, with two further institutions still to come.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A workshop in Spain took a different route to the same result. <a href=\"https://profiles.wordpress.org/josepmoran/\">Josep Morán</a> ran two four-hour sessions for 100 vocational students at Escola Pia Sta. Anna in Mataró, who used Playground and AI assistance to build a working plugin that calculates the best time for shore fishing in the city. Students and faculty pointed to the same two takeaways afterward: the certificate they received, and the fact that the skills map onto jobs that exist locally.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Workshop Without Power</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Bulamogi College Gadumire is on the list of Campus Connect schools in eastern Uganda because of Mariam Nairuba. At an event in Kaliro last December, she asked organizer <a href=\"https://profiles.wordpress.org/mosescursor/\">Moses Ssebunya</a> whether the program could come to her former school. She handled the arrangements with the administration herself, and on July 29 she navigated the team there. More than 100 learners were waiting. So was the school&#8217;s Director of Studies, who learned that day there was no electricity.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The team had brought laptops, a projector, and extension cables, none of which were useful now. Rather than cancel, they put two questions to the room instead: what do you already know about WordPress, and what would you like to know? &#8220;The room exploded,&#8221; the organizers wrote in their <a href=\"https://events.wordpress.org/campusconnect/2026/central-eastern-ug/gadu-maya-wordpress-campus-connect-finds-a-home-at-bulamogi-college-gadumire/\">recap of the day</a>. Students asked whether WordPress was free, how secure WordPress sites really are, and whether they could become developers themselves. John Wayera, one of two first-time volunteers alongside Nairuba, wrote the questions up on the blackboard as they came. The team copied down every answer. Before they left, they presented the school with a Certificate of Appreciation, which the Head Teacher received in front of the governing body.</p>\n\n\n\n<figure class=\"wp-block-gallery alignwide has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large is-resized wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21628\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/09/image.png?resize=1024%2C576&#038;ssl=1\" style=\"width: 624px; height: auto;\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large is-resized wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21629\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/09/image-1.png?resize=1024%2C576&#038;ssl=1\" style=\"width: 624px; height: auto;\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large is-resized wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21630\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/09/image-2.png?resize=1024%2C576&#038;ssl=1\" style=\"width: 624px; height: auto;\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<h2 class=\"wp-block-heading\">Students Teaching Students in Costa Rica</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/roblesloaiza/\">Rita Robles Loaiza</a> <a href=\"https://make.wordpress.org/community/2026/07/31/exploring-new-ways-to-contribute-to-wordpress-through-wpcredits/\">published two pilots</a> built on the premise that the students who just learned this are the best people to teach it next. In the first, three students from the second WordPress Credits cohort at <a href=\"https://ufidelitas.ac.cr/\">Universidad Fidélitas</a> designed and delivered a workshop for 40 high school girls. The goal of the event is to encourage and increase female participation in STEM academic careers. Their venue was Patrones Hermosos, a science and engineering camp run by Tecnológico de Monterrey and MIT that came to Costa Rica for the first time this year. Every participant built and presented a website, satisfaction came back at 100 percent, and the team turned the whole thing into a <a href=\"https://make.wordpress.org/community/files/2026/07/EN_WPCredits-Replicable-Guide.pdf\">replicable guide</a> that any school or community group can pick up and run.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The second pilot has a longer horizon. Thirteen students at Liceo Experimental Bilingüe José Figueres Ferrer, the first high school in the Americas to join WordPress Credits, are working with the <a href=\"https://make.wordpress.org/polyglots/teams/\">Costa Rican Spanish Polyglots team</a> to translate WordPress into es_CR for their community service requirement. When they finish, WordPress will read a little more like home for every Costa Rican who installs it.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Get Involved</h2>\n\n\n\n<p class=\"wp-block-paragraph\">There is no cost to bring any of this to a school. Campus Connect gives an organizer a ready-made curriculum and a certificate for every student who completes it. WordPress Credits gives a student a mentor, real contributions to software that runs more than 40 percent of the web, and something concrete to put on a resume. Student Clubs give a campus group a reason to keep meeting after the workshop ends.</p>\n\n\n\n<div class=\"wp-block-group has-off-white-background-color has-background is-layout-constrained wp-container-core-group-is-layout-2431c55b wp-block-group-is-layout-constrained\">\n<h2 class=\"wp-block-heading has-text-align-center\">Education Initiatives</h2>\n\n\n\n<p class=\"has-text-align-center wp-block-paragraph\">WordPress Education offers three practical ways for learners to develop skills, gain practical experience, and build confidence as open source contributors.</p>\n\n\n\n<div class=\"wp-block-buttons is-content-justification-center is-layout-flex wp-container-core-buttons-is-layout-3e41869c wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://wordpress.org/education/credits\">Credits</a></div>\n\n\n\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://wordpress.org/education/campus-connect\">Campus Connect</a></div>\n\n\n\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://wordpress.org/education/student-clubs\">Student Clubs</a></div>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">The <a href=\"https://make.wordpress.org/community/2026/08/05/monthly-education-buzz-report-july-2026/\">full Monthly Education Buzz Report for July 2026</a> has the events that didn&#8217;t fit here, including a Campus Connect run entirely by students at Kyoto University of Advanced Science and a Student Club in Dhaka now organizing its own campus event.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 07 Sep 2026 23:19:34 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Destiny Kanno\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:36;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"Open Channels FM: A Blender Full of Tech Predictions\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561283\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://openchannels.fm/a-blender-full-of-tech-predictions/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:165:\"Predictions about technology and trends emerge year-round, but many can be trivial or obvious, lacking real insight or originality. But there are the golden nuggets.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 07 Sep 2026 14:19:10 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:37;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"Open Channels FM: Open Signal Launches. Real Talk from Open Channels FM Founder\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561316\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://openchannels.fm/open-signal-launches-real-talk-from-open-channels-fm-founder/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:111:\"Bob Dunn shares his perspective on open source and the web in the first (official) solo episode of Open Signal.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 07 Sep 2026 10:49:38 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:38;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:67:\"OpenStation Blog: OpenStation Brand: Feeding the machine with chaos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://openstation.blog/?p=510\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://openstation.blog/2026/09/04/openstation-brand-feeding-the-machine-with-chaos/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:8363:\"<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">This post is long overdue, but here it is. The process behind the OpenStation brand, which is, to date, one of the most fun projects I&#8217;ve ever worked on. <img alt=\"💜\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f49c.png\" style=\"height: 1em;\" /></p>\n</blockquote>\n\n\n\n<h2 class=\"wp-block-heading\">A name we didn&#8217;t have</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Here&#8217;s the crazy part: I started designing the brand before we even had a name. We had vibes, we had concepts, we had people brainstorming names, and zero idea what would come out. Eventually, after a lot of back and forth, we settled on <strong>OpenStation</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That opened the door to many possibilities. Mostly it opened the door to me finally being allowed to draw.</p>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 60px;\"></div>\n\n\n\n<h2 class=\"wp-block-heading\">Visual chaos</h2>\n\n\n\n<p class=\"wp-block-paragraph\">I started where I always start, which is paper. Advanced technology.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ugly little drawings, lines, the same shape drawn thirteen times&#8230; Then a couple (or a hundred) of hours on Pinterest saving anything that sparkled in my eyes, and a Figma board where I dumped it all and started grouping.</p>\n\n\n\n<figure class=\"wp-block-image alignfull size-full\"><img alt=\"\" class=\"wp-image-519\" height=\"2038\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/Screenshot-2026-09-04-at-09.04.20.png?resize=4358%2C2038&#038;ssl=1\" width=\"4358\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">And then, I started <strong>feeding the machines.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">I dumped my chaos to AI: a sketch, a color, a screenshot, a note that said <em>not this, more the other</em> (which is apparently a valid prompt now). It came back with fifteen things, half of them wrong. That wrongness sent me back to the board. I drew again. I fed it again. AI → Figma → Pinterest → AI → Figma&#8230; and repeat.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This, for three days.</strong></p>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 60px;\"></div>\n\n\n\n<h2 class=\"wp-block-heading\">Locking the concept: <em>Spaceholowave</em></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Don&#8217;t search for that because I invented it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s a mix between Space + Holodoor + Synthwave. I kinda wanted to play with some holographic and vibrant elements, Cyberpunk style, floating on the dark void.</p>\n\n\n\n<figure class=\"wp-block-image alignfull size-full\"><img alt=\"\" class=\"wp-image-524\" height=\"2450\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/Screenshot-2026-09-04-at-09.18.46.png?resize=3734%2C2450&#038;ssl=1\" width=\"3734\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">I was also obsessed with one reference: the <a href=\"https://nomanssky.fandom.com/wiki/Holo-Door\">holo-door from NMS</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I won&#8217;t go into the details of why I know this game or how many hours I spent playing it, but I also will add that on top of that visual reference, I had the Stargate door and Dragon Ball capsules.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You see where I&#8217;m going with this, right? Forcing all my nerd references into something that <strong><em>had to make sense</em></strong>.</p>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 60px;\"></div>\n\n\n\n<h2 class=\"wp-block-heading\">The logo + Mio</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Is it a holo window? A helmet? A candy? A marble? Yes. Or no. You decide, honestly, I&#8217;ve stopped thinking at this point.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What I knew was that the <strong>O and the S had to live inside the same shape,</strong> so it went through a lot of shapes until it became this:</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-535\" height=\"720\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-1.png?resize=2652%2C720&#038;ssl=1\" width=\"2652\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t know if Mio came before the logo or after. I think they happened to each other, actually.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But basically, the mark has two shapes: the ring, and the curve carved out of it, which looks like a blob. That&#8217;s Mio. Our station resident. He&#8217;s the logo&#8217;s negative space and turned into a small ghost that glows, making your space a tad more lively.</p>\n\n\n\n<figure class=\"wp-block-image alignfull size-full\"><img alt=\"\" class=\"wp-image-543\" height=\"1810\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-2.png?resize=7161%2C1810&#038;ssl=1\" width=\"7161\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-549\" height=\"420\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-4.png?resize=1024%2C420&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Designing Mio is probably one of the most fun things I&#8217;ve done in my adult years. <img alt=\"💜\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f49c.png\" style=\"height: 1em;\" /></p>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 60px;\"></div>\n\n\n\n<h2 class=\"wp-block-heading\">Merchandise makes things <em>real</em></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Logo and Mio in hand, I let the AI go bananas on merchandise. Holographic stickers, enamel pins, the works. We didn&#8217;t need stickers on day two. But nothing tells you whether a brand holds up like seeing it on a pin the size of a one-euro coin. If it survives that, it survives a favicon.</p>\n\n\n\n<figure class=\"wp-block-image alignfull size-large\"><img alt=\"\" class=\"wp-image-560\" height=\"374\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/Screenshot-2026-09-04-at-10.01.10.png?resize=1024%2C374&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">And little by little the brand was forming. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The types are <strong>Geist</strong> and <strong>Geist Mono</strong>: open source, <a href=\"https://vercel.com/font\">Vercel did a lovely job</a> with them, and they sit right where we live, somewhere between space and a terminal. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Colors were obvious: <strong>holo pink over the void</strong>. Something that stands out on a dark screen and, big point here, stays accessible. </p>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 24px;\"></div>\n\n\n\n<figure class=\"wp-block-image alignfull size-full\"><img alt=\"\" class=\"wp-image-563\" height=\"2480\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/Screenshot-2026-09-04-at-10.02.52.png?resize=5004%2C2480&#038;ssl=1\" width=\"5004\" /></figure>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 60px;\"></div>\n\n\n\n<h2 class=\"wp-block-heading\">The brand is alive</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Three days of brand sprint saved us weeks of &#8220;should this be rounder&#8221; conversations. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Not because the brand is perfect. Because the brand guideline is alive, public, and hooked into the agents we use, so anyone on the team can make a wallpaper or a widget icon and it comes out looking like part of one big happy Mio family. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Go poke at it yourself:</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://nuriapenya.github.io/open-station-brand/\">Brand guidelines</a></div>\n</div>\n\n\n\n<div class=\"wp-block-spacer\" style=\"height: 60px;\"></div>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you for reading this messy post <img alt=\"💜\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f49c.png\" style=\"height: 1em;\" /> and big shoutout to Nick Hamze, who showed up at WCUS with these amazing shoes:</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-573\" height=\"4284\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/IMG_1643.jpg?resize=5712%2C4284&#038;ssl=1\" width=\"5712\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 04 Sep 2026 08:12:47 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Núria Peña\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:39;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"bbPress: bbPress 2.6.15 is out!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://bbpress.org/?p=249736\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://bbpress.org/blog/2026/09/bbpress-2-6-15-is-out/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1405:\"<p class=\"wp-block-paragraph\">bbPress 2.6.15 is a security and maintenance release that fixes five security issues and includes a few compatibility improvements. Everyone running bbPress should update as soon as possible. <img alt=\"🔒\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f512.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">This release strengthens authorization around topic and reply editing, topic splitting and merging, user profile updates, and private or hidden forum visibility. It also hardens imported password verification, avoids PHP warnings on some forum requests, and improves compatibility with modern WordPress UTF-8 handling.</p>\n\n\n\n<p class=\"wp-block-paragraph\">All of these fixes have already been merged into the 2.7 development branch.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you to mickey_cyberkid, itznullbyte, eldoniis, and tristaninsec for reporting issues through HackerOne, and to Ananda Dhakal at Patchstack for reporting CVE-2026-74010. Thank you for helping keep bbPress communities safe! <img alt=\"🙏\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f64f.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://downloads.wordpress.org/plugin/bbpress.2.6.15.zip\">Download bbPress 2.6.15</a> from WordPress.org, or update directly from your WordPress dashboard.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 03 Sep 2026 19:54:14 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"John James Jacoby\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:40;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"Open Channels FM: Podcasting Meets AI Shifting Formats, Editing, and Ethics\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560946\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:80:\"https://openchannels.fm/podcasting-meets-ai-shifting-formats-editing-and-ethics/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:93:\"Examining the impact of AI on podcast content, marketing, and the value of real human voices.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 03 Sep 2026 14:05:14 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:41;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"WPTavern: #232 – Aaron D Campbell on Navigating WordPress Security in the AI Era\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=207822\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:96:\"https://wptavern.com/podcast/232-aaron-d-campbell-on-navigating-wordpress-security-in-the-ai-era\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:54128:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, navigating WordPress security in the era of AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Aaron D. Campbell.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Aaron is a seasoned veteran in both the internet and WordPress space. With over 25 years of experience spanning agency work, security products, hosting giants like GoDaddy and Newfold, and now his role at Monarx, a company focused on malware detection and remediation, particularly for web hosts. He&#8217;s led, the WordPress Security Team, has been involved deeply in shaping security practises, and remains tightly connected to the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the rapidly changing landscape of WordPress security, specifically how the advent of AI has escalated the speed, scale, and complexity of attacks, moving the security game from a battle of wits to a battle of compute power. Aaron discusses how attacks that once required human ingenuity are now orchestrated by AI agents, capable of chaining vulnerabilities that humans would struggle to conceive.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We get into the shift from a reactive to a proactive security posture across the WordPress ecosystem. Aaron explains how both attackers and defenders are now deploying AI leading to an arms race, where AI is used to combat AI, and where collaboration among security teams is just as crucial as information sharing among adversaries.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Which chat about the motivators behind attacks, spoiler, it&#8217;s almost always money. And the specific vulnerabilities WordPress faces as the most popular CMS on the web. Of interest is the narrowing window between when vulnerabilities are discovered and when they&#8217;re exploited, how supply chain attacks are on the rise, and what the WordPress &#8220;Protect the Shire&#8221; innovation means for plugin security.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end of the episode, we explore practical security advice for everyday WordPress users, with Aaron, recommending actionable tips on updates, choosing security minded hosts, and monitoring for Compromise credentials.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you are concerned about how AI is reshaping the WordPress security landscape, and want to know how the community is responding, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Aaron D. Campbell.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Aaron Campbell. Hello, Aaron.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:43] <strong>Aaron D Campbell:</strong> Hello, nice to be here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:44] <strong>Nathan Wrigley:</strong> Yeah. Thank you for joining me. We&#8217;re in a corridor. I should say that at the very beginning. We&#8217;re in a corridor at WordCamp US, and so if background noise becomes a problem, we&#8217;re just going to have to cope with it. So apologies. But thank you for joining me in a corridor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:57] <strong>Aaron D Campbell:</strong> Absolutely.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:58] <strong>Nathan Wrigley:</strong> We&#8217;re going to talk today a little bit about WordPress security, and particularly about the advent of AI, and the way that certainly in the more recent past, it appears to have upended what once was normal, I think it&#8217;s fair to say. I think things are happening at a rate of knots that perhaps a year or two ago we wouldn&#8217;t necessarily have predicted.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you want to just give us a little bit of background about yourself in terms of where you have worked, where you currently work, and what it is that you do for a living?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:25] <strong>Aaron D Campbell:</strong> Sure. So I guess I have worked in the internet space for a very long time at this point. I guess 25 years-ish. Ran my own agency for a long time and then into security product in the WordPress space, and over into hosting at GoDaddy, at Newfold, at hosting.com.</p>\n\n\n\n<p class=\"wp-block-paragraph\">During that time I ran the WordPress security team for a couple years, have continued to be involved with it along the way, and now I am over at Monarx. We do malware detection and remediation, and have some security tooling for web hosts. So I&#8217;m still very tightly tied into that space on a few fronts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:09] <strong>Nathan Wrigley:</strong> Is Monarx a new company? Because it&#8217;s not one that may necessarily come into mind when we talk about security online, WordPress security specifically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if you&#8217;re willing, could you just give us a little bit of a potted history of Monarx and what specifically you do in the WordPress space? I think it&#8217;s perhaps more related to hosting companies than it might be to end users. Just flesh that out a little bit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:33] <strong>Aaron D Campbell:</strong> Yeah. Monarx has been around probably longer than you expect, six or seven years. The name&#8217;s may be not as recognisable, because a lot of times we are a white label in the background. Hosts run us, and you may not know that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We protect more than just WordPress, but obviously WordPress is a big part of that. And we help hosts keep their users, their end users, safe and secure and malware free by monitoring the files, the runtime, having a WAF layer, protecting it several different layers along the way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:08] <strong>Nathan Wrigley:</strong> So is this kind of like a white label solution? You are in talks with hosts, many of which I&#8217;m sure we&#8217;ve heard of, but their purchase of the products and services that you sell is white labelled.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:20] <strong>Aaron D Campbell:</strong> Yes, they may sell us as their own security product. They may also just include us in higher end hosting packages so that the malware detection and remediation and all that kind of stuff is included in your package. It varies from host to host, but most of the time you&#8217;re not seeing the Monarx name out in front, but you&#8217;re benefiting from our services anyway.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:40] <strong>Nathan Wrigley:</strong> So does that allow you to, because you are cross platform in terms of hosting company, hosting company X, hosting company Y, hosting company A, B, and C. Does that give you a larger depth of knowledge for want of a better word? So you can see that hosting company A&#8217;s got this Linux set up, and these kind of things are happening.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:59] <strong>Aaron D Campbell:</strong> Yes, it does. It&#8217;s less about their specific setups. I think the most valuable thing of being across many hosts like that, is that we see attacks, or new and novel malware, or those kinds of things happening in pockets and can often then protect against it globally, even though maybe it first started at host A.</p>\n\n\n\n<p class=\"wp-block-paragraph\">By the time it spreads to host B X or Y in your example, we&#8217;ve already been able to understand what that is and block it across the whole realm. So we get a bigger picture, which is super useful. Especially as we start talking about some of the AI stuff and how fast it moves. That&#8217;s really necessary to stay ahead of that curve.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:42] <strong>Nathan Wrigley:</strong> Okay, so let&#8217;s move into that a little bit. And I think if we were having this conversation, let&#8217;s go for four years ago, that seems like a long enough period of time where AI was not really on anybody&#8217;s menu.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And now we seem to be in the era where the human is really being surpassed in almost everything logical, let&#8217;s go with that word. If it can be achieved with some kind of logic then AI seems to have surpassed humans.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, especially recently, there seems to have been an uptick, not just in the WordPress news cycle, but also just in the general news cycle about, okay, we need to be a little bit more mindful about the products and services that we buy. We need to be more mindful about the security and logging in and credentials and all of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But specifically in the WordPress space over the last three or four months, I&#8217;ve heard story after story, which was unlike anything I&#8217;d heard before. These kind of chained attacks where, something that a human probably would never have conceived and pulled off is now possible. You spend 25 US cents on an AI agent, wait for six hours, and it&#8217;s come up with these 14 overlapping things, and it can hack WordPress Core and various other things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So just paint the landscape of how alarming it is, and then presumably you can paint the landscape of how not alarming it is, because how you can mitigate against that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:00] <strong>Aaron D Campbell:</strong> That&#8217;s fair. Let&#8217;s explain the reality and then let&#8217;s hopefully, help comfort people at least a little. It can be pretty scary. You&#8217;re absolutely right. AI has dramatically changed the game. And the way I like to explain it is it hasn&#8217;t changed the absolute core realities of the game in that there&#8217;s still a bit of cat and mouse. They&#8217;re trying to surpass us. We&#8217;re, trying to stay ahead of them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the scale and the speed and the complexity at which it is able to happen now is nothing we could have imagined four years ago. Honestly, even two, two and a half years ago. It has moved that fast. And what that looks like are, a few different things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One, the speed at which AI can find issues in code, potential exploits, vulnerabilities, et cetera, is so much faster than any human. Like the compute power of it doing those logical bits rather than humans doing those logical bits, makes that move so fast. So the number of things being found, and being either reported or exploited, or both, the volume has just gone up dramatically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then on the complexity side of it, you are right. A simple example of that, one of the WordPress Core reports that I looked at recently, I needed to print it out and mark it up with a pen to wrap my brain around all these steps that it was taking. When I printed it out, it was 11 pages. 11 pages of like steps and instructions for an actual vulnerability that turned out to be real.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If four years ago that had existed in your piece of software, you would consider your software absolutely secure. No human&#8217;s ever going to find that. No one would ever know about it. And now AI is able to chain all those steps together into something that it can then write scripts to go automate and exploit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so those two things have both really shifted the game in a way that feels like it can put software owners, software managers, SaaS services, all these things on their back foot. There&#8217;s just such this flood, and such a complex flood coming at you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:10] <strong>Nathan Wrigley:</strong> So I guess also the problem is that these things never sleep. So four years ago, every human, maybe they could put 10 hours in at the computer and then they would have to rest. So you get a, breathing space, and and the human can do this one thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But that&#8217;s not the case here. With an AI, presumably it could have 10, 50, a hundred, a thousand, the sky is the limit, things happening simultaneously. Just testing absolutely every permutation of everything conceivable. And then coming back with something. I don&#8217;t even know how we compete against that. And obviously we can get into that in a moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Is this a moment of despair or is there genuinely a way of getting out ahead of it? Or is it always going to be a case looking into the future where you are going to be reactive instead of proactive? In other words, when you wake up in the morning and you print out the 11 and then next year, the 30, and then the year after that, the 80 page document, how does that make you feel? Are you sanguine or is it just a prophecy of doom.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:08] <strong>Aaron D Campbell:</strong> I think it is a time of overwhelm, but hopefully not despair. Which is different. And I think that as big technology shifts hit, which AI is a big technology shift. There is often a significant adjustment. And we are at that time, and I am even one that maybe would say, I think it might get a little bit worse before it gets better, but it&#8217;s definitely going to get better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I see the path there in some of the foundations that we&#8217;re laying in things that we&#8217;re learning right now during this time of overwhelm, where we&#8217;re feeling flooded like this, is going to put us in a place to start getting into that curve where everything gets better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think that, what&#8217;s the right way to put this? I think that the path there is apparent, but takes some time. And part of that&#8217;s because we have to shift from the being reactive to the being proactive all the time. Because agents move so fast to 24 hours a day, seven days a week. And the second they find a thing, they can immediately, automatically start trying to exploit it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We have to shift to being ahead. Because there is no longer a gap in between when a thing is found and when it&#8217;s exploited, for us to fix the thing. We have to get ahead.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:36] <strong>Nathan Wrigley:</strong> So, you are obviously deep in the weeds of this, and it sounds like you&#8217;ve got an intuition that at some point in the near to midterm future, you feel like you are going to reach a point where things start to improve. That was the implication, I think of what you said.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What is that intuition? How do you come to the conclusion that there is an opportunity for things to improve. Even if you need to go into the weeds a little bit. I&#8217;m curious as to how it&#8217;s not a prophecy of doom, and how you believe that a moment will arrive where, I can&#8217;t answer that for you. I&#8217;ll just open it up.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:06] <strong>Aaron D Campbell:</strong> Yeah. So I think that some of this comes from historical experience, right? We&#8217;ve had these kinds of experiences where say, a certain type of hash that we used for security became a thing that hackers could break with the level of computing power that they finally had access to.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that felt doom and gloom. But also we created better hashing algorithms. We created better things that were able to counteract that. We were able to shift to those, and we were also able to learn from them and think further forward.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So now some of the algorithms that we&#8217;re using aren&#8217;t just better enough to handle current computing, but better enough that we think they&#8217;re going to last a decent ways into the future.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think that there are similar things with AI now. Where we are leveraging the same kind of tools now that these bad actors are, and we&#8217;re learning how to use them not just to protect against the way the bad actors are using them, but to get ahead enough to stay ahead of them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the way that looks, because that sounds maybe too vague to be realistic I guess, is we&#8217;re not just running those same algorithms against our code, or those same models against our code and hoping that we find the stuff before they find it. We&#8217;re instead also looking at how can we push to a different part of the stack? How can we protect against things that we&#8217;ve never seen? How can we start to recognise these patterns so that we can look at behaviours and protect against those, rather than just flaws that need to be patched. It&#8217;s shifting our thinking some, but I think in a way that&#8217;s going to help us get ahead in this game.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:03] <strong>Nathan Wrigley:</strong> Okay. That&#8217;s really interesting. I have a question surrounding how this kind of stuff happens, and I&#8217;m thinking about it from the adversarial&#8217;s point of view. What is that like? Because I have a notion that a decade ago it was individuals, perhaps offices, that&#8217;s probably the wrong word, but, collections of people sitting in a space, but there would be a finite number of them. There may be 10 in a room, one in a room, a hundred in a room.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I don&#8217;t know if that&#8217;s still the case. Do the adversaries that you are dealing with, do they have a collaborative approach to hacking? Do they share information? And then the flip side of that is do you also, in the industry that you work in, do you share information?</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you discover something, does Monarx treat that like it&#8217;s your intellectual property? Or is there a, a whole system of sharing that amongst the community so that everybody benefits from the work that you do? You&#8217;re giving away the hard work that you&#8217;ve done. If that&#8217;s the case.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:59] <strong>Aaron D Campbell:</strong> So, first let me just say personally, one of the most important things to me is to raise the level of security across the whole internet, because that is better for humanity that relies on it so much, for all kinds of things in our daily lives, and for sharing information and making progress forward as people.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think that I&#8217;m not alone in the space. Like I think that a lot of us that were drawn to this security space are drawn to it because it is a way to improve life for everybody. Will there be some intellectual property for individual companies? Yes, but I think it&#8217;s a lot more in how we approach the thing, and less we&#8217;re not going to tell people about this new vulnerability, or this new method that we found. Because we do want to be able to see the end user protected. Like that is the way we&#8217;re going.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Backing up to your, how do the adversaries work? It&#8217;s been a long time, I think since they sat in rooms together. They&#8217;re now virtual rooms, right? They can be spread all over the world, but still be working together. And they definitely do. They share information around. For us to be able to keep up with that, we have to share information around too. That is super important.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Simple example of that, the WordPress Security Team. Let me step back from Monarx and talk more of the space in general. The WordPress Security Team. You talked about how for the last few months you&#8217;ve seen maybe more security releases going out from WordPress and stuff. The way that the WordPress Security Team treats those, when we find out about them, and we triage them, and we realise that they&#8217;re real, and we start figuring out what our approach is to patching them. We then have a whole private Slack channel that has other people in it that can help us get protection out. Broader, wider by sharing some of that information sooner.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Cloudflare can maybe put some rules in place, and protect tonnes of people before the WordPress release goes out. So can some of the big hosts. So can some of the security groups. And so not only do we share that information, we&#8217;ve built it into our processes as a must, because that&#8217;s the only way to really do it right, and really protect as many people as possible. Because our adversaries are doing that. And so we have to as well. And we&#8217;ve just realised that, learned from it and made that the right way to do it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:26] <strong>Nathan Wrigley:</strong> I&#8217;m just going to flip back to the comment that you made a moment ago where you said that you woke up and you printed out this summation. Let&#8217;s go with that. And it was 11 pages, and presumably that took a certain amount of your day to parse and understand.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How likely is it that that process will begin to run away from humans&#8217; capacity to actually do it? So as an example, let&#8217;s say that a year from now that thing that you print out is 50 pages or 80 pages. Just the reading of it would be a whole morning, let alone the understanding of how those layers, and the stacks and the way that they&#8217;re overlapping and reliant upon each other.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Have we now, or have you now as an industry, have you almost handed the responsibility to figuring that stuff out, figuring out what the adversaries are doing? Has that gone to AI from your part as well? So is it AI versus AI basically, which seems very dystopian.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:18] <strong>Aaron D Campbell:</strong> We definitely pit AI against AI. It&#8217;s an extremely useful tool to combat itself essentially. And yeah, even for that 11 page one. Yes, I had to read through it and figure it out. but I did use AI to help summarise that. What are the steps that I need to do? Where does this actually track to in the code base?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I use it as an assistive tool in getting through that. And I do think that the longer the reports get, the more that&#8217;s going to be necessary. And now I personally, and several other people that I work with, have built testing rigs in AI, in various models, that are purpose built to help with this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I can give it a report, in the repository and it can check its viability. It can see if that&#8217;s simplified. Check certain things. Is this a thing that requires some level of authentication, all these things that we use to have to do manually. And now we&#8217;re sharing around these sort of test rigs, or assessment rigs, that use this so that we can all use them, and grow them faster and make them better and make them more efficient. Because we are pitting AI against AI in many ways.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And as human, I think that it&#8217;s still important for the human to guide the process in a way that&#8217;s ensuring the fix is forward thinking enough, and that it&#8217;s in the right place and whatnot. Because in the end, the software is largely used by humans. But, in order to scale to the level that AI is pushing us to scale to, the human needs to be the decision maker, and possibly the opinionated one on form, and function, but not the logical power behind any of it now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:01] <strong>Nathan Wrigley:</strong> Do you get the sense that WordPress itself is the target, or is WordPress just a bit of collateral damage? Are these adversaries of yours, are they specifically targeting WordPress because it&#8217;s got this giant footprint? Or is it more a case of this is just the adversaries just spraying and scatter gunning, and it just so happens that every so often they stumble across a WordPress thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:23] <strong>Aaron D Campbell:</strong> There is spray and scatter gun, just not running WordPress, or running your own bespoke thing is not enough to get away from AI trying to break your thing. But the bigger you are, the bigger the potential benefit from finding an exploit in you. And therefore, the more you are, like the bigger you are, the target is on you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So WordPress has a big target, but it&#8217;s not just WordPress. Some big hosting companies also have a big target on their infrastructure in the same way that they&#8217;re targeting WordPress, their targeting, maybe a Hosting or a GoDaddy or a Blue. Someone big that has many people on it, not because they think their security is lax, or that they have some reason to suspect that there&#8217;s vulnerabilities, but because the payoff of finding a vulnerability there can be big. And so there&#8217;s a big focus there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yes, the bigger you are, the bigger the target. But that doesn&#8217;t mean that the scattershot isn&#8217;t also happening. And that they&#8217;re not also hitting small targets.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:24] <strong>Nathan Wrigley:</strong> Yeah. I suppose there would&#8217;ve had to have been a lot of joined up thinking in the past from a human to discover that, &#8220;Okay, this thing with Linux over here, okay we&#8217;ll just store that somewhere. But then there&#8217;s a PHP thing over here. Oh, and then curiously, there&#8217;s a PHP thing in WordPress, which,&#8221; that would&#8217;ve all had to have been conjured up by a human. And the memory of that would be difficult to maintain over time. But presumably the AI can just remember that forevermore. Store that PHP thing for the next decade and suddenly whip it out when it&#8217;s happens to coincide with some other thing. It&#8217;s fairly bleak.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, so in terms of WordPress specifically, what is the incentive specifically? Why would somebody, let&#8217;s say somebody was coming after WordPress. What is it that they gain? What could they possibly have that benefits them off the back of a, let&#8217;s go for WordPress Core vulnerability which is, I don&#8217;t know, you can successfully log in as an admin or whatever it may be. What do they actually gain?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:17] <strong>Aaron D Campbell:</strong> It really comes down to money in end, if I&#8217;m honest. WordPress Core powers tens of millions of sites all over the web. Some of those have valuable stuff on them. Many of them frankly don&#8217;t. But that doesn&#8217;t mean that they&#8217;re worthless. They can be used, you&#8217;ve seen pharma ads and stuff showing up on a site, and it&#8217;s a pay per click kind of thing. And someone&#8217;s making some money off of putting not great ads your site. Even if you don&#8217;t get a lot of traffic, they&#8217;re making something. And when you&#8217;re looking at the potential of this vulnerability could apply to tens of millions of sites, you don&#8217;t need to make much per site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But also, you could use that site as a way to have broad compute power to attack some other site. You&#8217;re using tens of thousands of sites to do it. Each one of them is on some separate IP. So now you have a distributed attack that&#8217;s harder to block than if you were doing the same attack from one place.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But you&#8217;re only doing that because it costs a lot to buy your own distributed power from everywhere. So you&#8217;re essentially stealing it and it&#8217;s making it, there&#8217;s some sort of worthwhile monetary value from it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so you may think, they can&#8217;t make anything off my site. They don&#8217;t have to. Your site&#8217;s one small bit in a huge array of sites that they&#8217;re trying to get, to get some monetary benefit in the end.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:40] <strong>Nathan Wrigley:</strong> So there&#8217;s no one size fits all. But money is essentially the broad overlapping thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:46] <strong>Aaron D Campbell:</strong> I mean, there are exceptions to that, where people are doing it for some political reason. Or some moral directive that they have or whatever. But the vast majority can be traced back to there&#8217;s money in it somewhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:59] <strong>Nathan Wrigley:</strong> I wonder curiously, because you mentioned about things like, pay per click style, you take oversight and you flood it with, I don&#8217;t know, nonsense about the thing that you&#8217;ve got and you want the world to notice. I wonder if curiously, people&#8217;s adoption of AI and that different way that we&#8217;re searching for things will actually impoverish that way of monetizing, because simply nobody&#8217;s actually looking on a search, well, increasingly people seem to be relying less and less on a search engine, and so maybe that kind of bit of it will dry up. Who knows?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:27] <strong>Aaron D Campbell:</strong> I love the optimism there. And I would like to think that those ads specifically probably will at some point. But the root of how those work is, I&#8217;ve broken into a site and I can inject some JavaScript ad, or some something like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And if those ads stop being valuable, then maybe I can inject some AI directives so that when an AI agent of some kind hits that site, it&#8217;s getting some sneaky thing snuck into its memory, or pulled in as a skill, that can then use that AI agent for nefarious purposes in the future.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think that we can&#8217;t lower our guard against those things, because our adversaries will pivot and reuse it for something else. And so we will continue to protect against it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:13] <strong>Nathan Wrigley:</strong> I&#8217;m going to peel back the contents of your head a little bit here. Because I&#8217;ve often wondered what the characteristic is of somebody like you who constantly facing this tidal wave of things. You&#8217;ve got to get up every morning, and every morning you could potentially wake up to the next big thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How do you just remain calm in the face of all of it? It&#8217;s a peculiar question, I realise, but tomorrow could be the next big thing. The day after that could be the next big thing. I&#8217;m imagining on most days now there is not necessarily the next big thing, but there&#8217;s a thing. It&#8217;s like you&#8217;re a fireman or something, except that there&#8217;s a fire going off in every district of town, and you are constantly busy and you never get to put the fire hose down. You&#8217;re just constantly at work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:52] <strong>Aaron D Campbell:</strong> Some of us love that little consistent regular shot of adrenaline, and we get it in different ways than the firemen. But, honestly, I love complex problems solve. I love the challenges. Do I get exhausted and burnt out at times when they really do come every day for X amount of time? Sure, I&#8217;m human, I need to sleep, et cetera. But I think that it&#8217;s because I enjoy figuring out those really difficult problems, that I enjoy being in this space. And even specifically on this side of the space, the white hat side.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:26] <strong>Nathan Wrigley:</strong> Yeah. I suppose it&#8217;s like playing a good opponent at chess. You enjoy the chess game, even though it&#8217;s a hard thing and it stretches your brain. You play the chess over and over again because it&#8217;s a pleasurable thing to have your brain exercised in that way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:39] <strong>Aaron D Campbell:</strong> And it&#8217;s like the more you do it the better chance you have at winning at chess. And I think it&#8217;s the same way in our game, right? Like the more you&#8217;re doing it, the more ways you&#8217;re finding to outmanoeuvre and to essentially win, and keep people safe online. And that&#8217;s, that&#8217;s exciting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:56] <strong>Nathan Wrigley:</strong> You get the fist pump moment do you, there&#8217;s once in a while where you literally figure something out and you&#8217;re like, I nailed that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:04] <strong>Aaron D Campbell:</strong> You absolutely do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:04] <strong>Nathan Wrigley:</strong> Okay. Yeah. That&#8217;s really interesting. Your bio reads like an open source manifesto. I know that open source has been the thing for you throughout your career. I imagine that you could have gone into proprietary security and all of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But how does open source, particularly WordPress, how does that approach to developing software, how does that benefit the position that we can take and the security posture that you can take, and the reliability that you can have in things like WordPress going forwards? In your head, does it offer a superior model for fighting the adversaries?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:35] <strong>Aaron D Campbell:</strong> Yes, in my opinion it offers a superior model for fighting the adversaries. And the reason is actually still the same as it was 20 years ago when I started doing this. And I&#8217;ll explain why in just a second, but first, the reason is because we are able to benefit from many intelligent people, many more than any single company could with their source code.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Looking at our source code, and finding the weaknesses and even pitching in to help fix them. Hundreds of thousands, or millions, of people around the world are looking at our source code, finding those issues, and able to help pitch in and fix them, or report them to us so that we can, by having all that out there, it&#8217;s sort of like a building&#8217;s not less likely to collapse because no one saw the crack. It&#8217;s actually better that people are inspecting it, and finding those things and making sure it&#8217;s done right.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, that has shifted a little bit now, where in the past our adversaries looked at our source code too, right? They would immediately look at our repository when new things went out. As a matter of fact, when I ran the security team, I stopped committing stuff for a while, because it turned out that was a tell that this thing was probably a security issue, and people would look at that and try to figure it out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So now the adversaries are using AI to watch our source code, which is also open to them, 24 7 and really look deep at it. But so are those many thousands of people using our source code for good. And so it&#8217;s still true that we have so many people on our side in helping us out, because our source code is out there because we&#8217;re open source, and it outweighs the bad. We find things faster because of that, and ultimately end up with more secure software more rapidly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:36] <strong>Nathan Wrigley:</strong> Is there ever going to become a time where the amount of time that a vulnerability is available becomes moot? So in the past, a six hour window, where something wasn&#8217;t patched in WordPress Core, that&#8217;s a thing, but it&#8217;s not really a big thing. Maybe a month where something&#8217;s unpatched, that&#8217;s a big, I&#8217;m just wondering if in the future with the nature of the adversaries that you described and the tooling that they can bring to bear, if even like a three or five second window is going to become a thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:05] <strong>Aaron D Campbell:</strong> That is possible. We&#8217;re not at the three to five second window yet, so that&#8217;s good. I&#8217;ll let everybody relax a little bit. But the time from vulnerability disclosure to exploitation has shrunk dramatically over the last few years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We did in fact used to have weeks, and then eventually days where it was okay to find out about the vulnerability, and responsible people, or responsible hosts, or responsible software companies could see that disclosure, patch the problem before there was much exploitation at all. And that&#8217;s now hours for major vulnerabilities.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As a matter of fact, we did a Monarx in conjunction with Patchstack, did like a year in review, thing looking back at last year. And we saw that for the more major vulnerabilities, it was about five hours. That&#8217;s not enough time for, you know, what happens if it happens in the middle of the night for a host who&#8217;s constantly monitoring that, immediately patching it, that&#8217;s difficult. And I do think that it will continue to shrink. And that that time that causes risk will be shorter and shorter.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, we saw that with the recent wp2shell WordPress exploit. Once we released the patch, and everything was out there, the spike of exploitation that we as Monarx saw, like monitoring stuff happened within 30 minutes. Honestly, even a little bit faster than that. But the big spike started coming in about 30 minutes later, and that is just really fast.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But on the flip side, all that coordination that I talked about that WordPress did, had many millions of people already protected by then. And that&#8217;s how we have to look at it. We have to say, this is eventually going to get down to three to five seconds being a problem. How do we get ahead of it? And that&#8217;s what we&#8217;re trying to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:03] <strong>Nathan Wrigley:</strong> So a timely thing at the moment is this new innovation in the WordPress space called Protect the Shire. And Protect the Shire is the, a time bound moment where a plugin that has an update, it can&#8217;t be updated at the moment, I believe it&#8217;s standing at something in the region of six hours. On the face of it, that seems like a really excellent posture. But then there&#8217;s the flip side of that. If an exploit becomes discovered, and nobody can update their plugin for six hours, then that&#8217;s a big six hour window we&#8217;ve just painted. in the future where milliseconds may count. What do you think about that? It&#8217;s a interesting innovation. It&#8217;s something new. It was worth a try. Do you think that&#8217;s the way forward?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:41] <strong>Aaron D Campbell:</strong> I think it, was not only worth a try. I think it was a really good choice, and I think it will continue to be. We are seeing that a lot of current attacks are essentially supply chain attacks. How can we compromise whether it&#8217;s some package, an NPM package or something like that. Or whether it&#8217;s a plugin that&#8217;s gotten sold to a nefarious person, or even just hacked into and taken over by a nefarious person. That is happening more and this six hour gap helps protect against that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it can&#8217;t be a hard and fast, locked in stone, can never have exceptions, rule. And the truth is, it&#8217;s not. If there is a vulnerability in your plugin, or especially in a major plugin, reach out to the WordPress Security Team because we can coordinate a faster release, we can make an exception to that rule when it&#8217;s necessary.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think that for security fixes that are clearly security fixes that exception iss an easy one to make, because we do want to protect immediately. But slowing things down enough to make sure that there&#8217;s not been some sort of supply chain issue that is actually going to cause a vulnerability rather than fix one, is smart.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so I think that it will find the right balance there as we continue to move forward, and figure out how to make better processes around this, to make it easier to do the right thing all the time, and know exactly which of those right things. But I think at the moment we&#8217;re in a pretty good place there and continuing to find the exact right place.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:18] <strong>Nathan Wrigley:</strong> It feels from the outside as if security&#8217;s fairly binary. On the one hand, adversary on the other hand, good guys. On the one hand hacked, on the other hand, not hacked. It&#8217;s black and white. But it seems from everything that you&#8217;ve been talking about today, that you are occupying a really grey area. You&#8217;re just trying to figure out what the path is forward. You&#8217;re constantly staring into the future trying to figure out what the adversaries are doing. Trying to patch, trying to make sure that everything is as good as it possibly can be. And I hadn&#8217;t really thought about it in that way. It&#8217;s not, there is no destination here where everything&#8217;s white. It&#8217;s a journey and every day&#8217;s going to be a bit grey. There&#8217;s going to be a bit of black and a bit of white, but a lot of grey in the middle.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:58] <strong>Aaron D Campbell:</strong> I don&#8217;t really look at it as grey, but I can see where you&#8217;re going there. But I think that there is this black and white, and then there&#8217;s sort of the cloudy. The further forward you look, the more difficult it is to know exactly where the black and white are always going to be. And some of that sort of comes across as grey. It&#8217;s a little blurry. You can&#8217;t quite figure it out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But you&#8217;re right. there&#8217;s some prediction. There&#8217;s some, we think that moving this way is going to cause more white and less black. And that&#8217;s what we&#8217;re, that&#8217;s what we&#8217;re constantly aiming for. But you can&#8217;t just say turning right always makes things more white. Because sometimes there could be black over on that side somewhere, right? You&#8217;re really trying to be predictive, but not just randomly predictive, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Many of the people like myself that are trying to help guide this path forward, and even more than me, some of the people like Matt, who instituted that wait policy and some of the people that are running the WordPress Security Team, we have decades of experience watching this, that&#8217;s helping to inform our predictions. And so it&#8217;s not, we&#8217;re not just willy-nilly guessing. And I think that&#8217;s important to point out to the people that rely on us, to help guide them to the right space going forward.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:02] <strong>Nathan Wrigley:</strong> Yeah. Okay. So my schooling in chemistry was pretty basic, but I know that if I want to understand chemistry, my quickest way to do that is to rely on an expert, is to go and find a chemist who has years of experience. And, the same would be true here. I think most of us have probably not got the capacity to actually get a hold of what you&#8217;re saying. We, understand that your expertise is what we need to be listening to. But I&#8217;m just wondering for a typical WordPress user of whom many listen to this podcast, they have a WordPress site, but they&#8217;re not really interested in security, other than how it may impact their business.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I&#8217;m going to ask for some very basic advice here. What would be the 1, 2, 3 things that somebody using WordPress with no security credentials whatsoever. What would be the few things that you would advise them to either go and read, or go and do, or go and think about?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:51] <strong>Aaron D Campbell:</strong> Yeah, so I think the biggest thing that I would encourage them to do, is essentially position themselves in such a way that they are relying on the experts, right? You&#8217;re not an expert and that&#8217;s okay. No one can be an expert in everything. But there are some things you can do to position yourself such that you&#8217;re benefiting from those experts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of those is updating as fast as possible. So WordPress auto updates turned on, those kinds of things. This WordPress Security Team that I&#8217;m talking about that has so much expertise in the area, and their whole focus is trying to make sure that WordPress is always secure. That lets you rely on them to help keep your site secure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think in similar ways, you want to find the right host that is also doing those security focused things for you, so that you don&#8217;t need to. And maybe that&#8217;s asking your host, what do you do to keep me safe? We talk about security, like the best security is layered security. It&#8217;s almost like having a gate at the complex, but also having a lock on your door, right? Those kinds of things. You can ask your host, what do you do to protect me in a layered way?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And maybe that question doesn&#8217;t make sense to you, and maybe even their answers don&#8217;t make sense to you, but if they have an answer, that&#8217;s good for you. It means that you can rely on their expertise.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then stepping out of the obvious space to give a third thing that people should be doing. And this is, this may sound out in left field, but you should get some form of dark web monitoring for yourself, for your own credentials. And whether that&#8217;s going to someplace like, Have I Been Pwned, and looking at your own email address, and passwords and seeing if they&#8217;ve been in some breached data from somewhere, and are now being sold on the dark web. Or whether that&#8217;s using some service that offers it. I think that&#8217;s important, more so now than it&#8217;s ever been.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because one of the other things that AI is doing that it&#8217;s particularly good at is collecting all this massive amount of breach data that&#8217;s happened over the last couple decades, that&#8217;s being sold on the dark web. Collating it all and saying, oh, we see that, gosh, 15 years ago, an account that Aaron had was in a breach. And we now know one of his passwords.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And granted it&#8217;s 15 years old, but it&#8217;s very easy for that AI to then say, where is Aaron now? What&#8217;s he doing? What can we learn about him? He works at Monarx. I wonder if this password works for his Monarx account. I wonder if this password works for the bank that he&#8217;s at. Or this other tool that we see that he uses. Let&#8217;s try all his social media accounts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so knowing whether that&#8217;s out there and being able to, you can&#8217;t get rid of that data, but being able to do things to protect yourself because you now know it&#8217;s out there is more important than it&#8217;s ever been.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:41:47] <strong>Nathan Wrigley:</strong> I hope you take this in the spirit in which it&#8217;s offered, but I really do wish to live in a world where you don&#8217;t have a job.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:41:55] <strong>Aaron D Campbell:</strong> Me too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:41:56] <strong>Nathan Wrigley:</strong> But, am glad that we live in a world where you do, somebody like you does have a job. So I hope that landed correctly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:02] <strong>Aaron D Campbell:</strong> If I could work to the point where I could work myself out of a job, I would find a new career and I would feel so accomplished, you couldn&#8217;t even imagine it. I&#8217;m okay with that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:12] <strong>Nathan Wrigley:</strong> Yeah. Good. Aaron, just before we wrap up, is there a place where you hang out online where people could poll you if they&#8217;ve got a question, or any thoughts about what we&#8217;ve talked about?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:21] <strong>Aaron D Campbell:</strong> Yeah, if you&#8217;re looking for me professionally, you can find me Monarx.com, M-O-N-A-R-X.com. I also have aarondcampbell.com if you want some of my own more personal takes on security and things. And you can find me on Bluesky or the WordPress Slack. Those are probably the biggest places I&#8217;m at.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:40] <strong>Nathan Wrigley:</strong> What I will do, dear listener, into the show notes, if you go to wptavern.com and you search for the episode with Aaron Campbell, you&#8217;ll be able to find the links. I will dig out the Bluesky, and the various social links and the Monarx website and what have you, so you don&#8217;t have to hunt around too much. Go there wptavern.com. And Aaron, thank you so much for chatting to me today.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:43:01] <strong>Aaron D Campbell:</strong> Thank you. This was a really fun talk.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have Aaron D Campbell.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Aaron is a seasoned veteran in both the internet and WordPress space, with over 25 years of experience spanning agency work, security products, hosting giants like GoDaddy and Newfold, and now his role at Monarx, a company focused on malware detection and remediation, particularly for web hosts. He’s led the WordPress Security Team, has been deeply involved in shaping security practices, and remains tightly connected to the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the rapidly changing landscape of WordPress security, specifically how the advent of AI has escalated the speed, scale, and complexity of attacks, moving the security game from a battle of wits, to a battle of compute power. Aaron discusses how attacks that once required human ingenuity are now orchestrated by AI agents capable of chaining vulnerabilities that humans would struggle to conceive.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We get into the shift from a reactive to a proactive security posture across the WordPress ecosystem. Aaron explains how both attackers and defenders are now deploying AI, leading to an arms race where AI is used to combat AI, and where collaboration among security teams is just as crucial as information-sharing among adversaries.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We chat about the motivators behind attacks, spoiler, it’s almost always about money, and the specific vulnerabilities WordPress faces as the most popular CMS on the web. Of interest is the narrowing window between when vulnerabilities are discovered and when they’re exploited, how supply chain attacks are on the rise, and what the WordPress “Protect the Shire” innovation means for plugin security.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end of the episode, we explored practical security advice for everyday WordPress users, with Aaron recommending actionable tips on updates, choosing security-minded hosts, and monitoring for compromised credentials.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re concerned about how AI is reshaping the WordPress security landscape, and want to know how the community is responding, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://aarondcampbell.com\">Aaron&#8217;s website</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.monarx.com\">Monarx website</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Monarx and Patchstack&#8217;s <a href=\"https://patchstack.com/whitepaper/state-of-wordpress-security-in-2026/\">State of WordPress Security In 2026</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://thehackernews.com/2026/07/wordpress-wp2shell-exploitation-grows.html\">WordPress wp2shell Exploitation Grows as Public Exploit Fuels Mass Scanning</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/news/2026/06/pts/\">Protect The Shire</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://haveibeenpwned.com\">Have I Been Pwned</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://bsky.app/profile/aarondcampbell.com\">Aaron on Bluesky</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 02 Sep 2026 14:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:42;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"Open Channels FM: Navigating Chaos in Tech Communities and New Approaches to SaaS and Sales\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560733\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"https://openchannels.fm/navigating-chaos-in-tech-communities-and-new-approaches-to-saas-and-sales/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:126:\"A candid conversation on contributor day turned hackathon, Cloudflare, product pivots, and the realities of founder-led sales.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 02 Sep 2026 13:27:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:43;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:174:\"HeroPress: Building Beyond the Screen: My WordPress, Accessibility, and OZD Katalog Story – Ekranın Ötesinde Üretmek: WordPress, Erişilebilirlik ve OZD Katalog Hikâyem\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://heropress.com/?post_type=heropress-essays&p=8812\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:224:\"https://heropress.com/essays/building-beyond-the-screen-my-wordpress-accessibility-and-ozd-katalog-story/#utm_source=rss&utm_medium=rss&utm_campaign=building-beyond-the-screen-my-wordpress-accessibility-and-ozd-katalog-story\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:24095:\"<img alt=\"Pull Quote: You do not need to possess every answer before you begin. - Başlamak için bütün cevaplara sahip olmak gerekmiyor.\" class=\"attachment-large size-large wp-post-image\" height=\"512\" src=\"https://heropress.com/wp-content/uploads/3026/09/sadik_heropress_banner.webp\" width=\"1024\" /><p class=\"wp-block-paragraph\"><a href=\"https://heropress.com/feed/#turkce\">Bu makale Türkçe olarak da mevcuttur.</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress has never been merely a content management system for building websites to me. As a blind web developer, it showed me that I could create my own field of work, solve real problems, and contribute to the same open-source community as people around the world. The publication of my <a href=\"https://haz.wordpress.org/plugins/ozd-katalog-eklentisi/\">OZD Katalog</a> plugin in the WordPress.org directory became one of the most visible results of that long journey.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-exploring-the-web-without-looking\">Exploring The Web Without Looking</h2>\n\n\n\n<p class=\"wp-block-paragraph\">My name is Sadık Özdoğan, and I live in <a href=\"https://www.google.com/maps/place/Ankara,+T%C3%BCrkiye/@38.7856907,30.5045406,7.28z/data=!4m6!3m5!1s0x14d347d520732db1:0xbdc57b0c0842b8d!8m2!3d39.9333635!4d32.8597419!16zL20vMGp5dw?entry=ttu&amp;g_ep=EgoyMDI2MDgyMy4wIKXMDSoASAFQAw%3D%3D\">Ankara, Türkiye</a>. I studied Web Design and Coding at Anadolu University in <a href=\"https://www.google.com/maps/place/Eski%C5%9Fehir,+T%C3%BCrkiye/@39.2123552,31.4230128,7.55z/data=!4m6!3m5!1s0x14cc3e08220c0e5f:0xbc89395938049a08!8m2!3d39.7667061!4d30.5256311!16zL20vMDcyeWZ2?entry=ttu&amp;g_ep=EgoyMDI2MDgyMy4wIKXMDSoASAFQAw%3D%3D\">Eskişehir</a>. Literature, poetry, and music are important parts of my life, but over the years web technology has also become a powerful means of expression and production for me. Because I am blind, I use my computer with the <a href=\"https://www.nvaccess.org/\">NVDA</a> screen reader. Instead of seeing the visual layout of a screen, I follow the structure of pages, headings, links, form fields, and text through synthesized speech.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This way of working means that a seemingly small accessibility error can become a complete barrier. An unlabeled button, an incorrectly built form, a message that is understandable only through color or imagery, or a control that cannot be reached with a keyboard may look like a minor imperfection to others, yet prevent me from completing a task. I did not want these barriers to distance me from technology. Instead, they encouraged me to understand how systems work and to create my own solutions.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-discovering-wordpress\">Discovering WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Discovering WordPress was an important turning point in that search. During my early years with it, I was mainly a user. I built websites, published articles, customized themes, tried plugins, and searched for solutions whenever something failed. The fact that much of the administration experience followed a recognizable structure and used text, headings, links, and standard form controls was valuable to me. WordPress was not perfectly accessible in every situation, but it gave me an open space in which I could publish my own content and gradually improve my skills.</p>\n\n\n\n<p class=\"wp-block-paragraph\">At first, I worked with existing themes and plugins. When I encountered a problem, I experimented with settings, read documentation and tutorials, and tried to understand the solution. In time, I realized that using tools was no longer enough for me. I wanted to know why a theme behaved in a certain way, which file controlled a function, and how an existing feature could be changed. That curiosity, which began with small code edits, gradually carried me from the user side of WordPress to the development side.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-building-without-looking\">Building Without Looking</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Customizing <a href=\"https://generatepress.com/\">GeneratePress</a> was one of my first serious learning experiences. I began by developing my own website and later built a radio website for a friend. I worked on themes for news, blogs, companies, and radio projects. Every project introduced a new problem that I had to break down and solve. Each detail I managed to fix increased not only my technical knowledge but also my confidence.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My working method as a blind developer is different in some respects. I cannot inspect indentation or the visual appearance of a page simply by looking at the screen. I move between files, lines, and components with the keyboard and turn the information spoken by my screen reader into a mental model. I ask people I trust for visual feedback when necessary, while relying on standards, testing tools, and repeated trials for technical validation. This has taught me that accessibility is not an optional feature added at the end of a project. Clear code, accurate labels, understandable language, and predictable behavior make technology easier for everyone.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-a-first-plugin\">A First Plugin</h2>\n\n\n\n<p class=\"wp-block-paragraph\">For a long time, I wanted to publish a plugin of my own. However, there was an obstacle greater than my technical limitations: I did not trust myself enough. Questions such as “What if I cannot do it?”, “What if my code is not good enough?”, and “What if the plugin is rejected?” kept me at the starting line. Sometimes people wait for their work to become perfect and therefore never share it. My real change began when I accepted that I could start before I was perfect and continue learning along the way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Artificial intelligence tools also supported my learning process. They helped me examine questions in greater detail, understand pieces of code, identify possible mistakes, and turn ideas into more systematic plans. They did not imagine the project on my behalf or create it independently. I was the person who recognized the need, decided which features mattered, tested the result, and accepted responsibility for it. Artificial intelligence, my screen reader, and my development tools all served the same purpose: helping me turn an idea in my mind into a working product that other people could use.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The idea for OZD Katalog emerged while I was building a website for a chair company. The company needed a clear and organized way to present its products. I initially created a catalog structure inside the theme. It could have remained a solution built only for that single project. As the work progressed, however, I asked myself: “Why should I leave this inside one theme? Why not turn it into an independent plugin and allow other people to use it?”<br /><br />That question was the true beginning of OZD Katalog. My aim was to help businesses display products in a catalog without requiring the full complexity of an e-commerce system. Administrators needed to be able to add product names, images, descriptions, categories, and relevant details in the dashboard, while visitors needed a clear way to browse the information. A need I had encountered in a real client project was becoming a general solution that could help others.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I prepared the earliest version of the plugin about a year before its release. Along the way, I learned that there is a major difference between code that works and a plugin that is ready for the WordPress.org directory. Security checks, capability controls, nonces, sanitization, and output escaping had to be handled carefully. Text needed to be translatable, files had to follow the correct structure, interface messages had to be understandable, and the code needed to follow WordPress standards. Every correction improved not only the plugin but also my discipline as a developer.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-releasing-my-first-plugin\">Releasing My First Plugin</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Eventually, I submitted OZD Katalog for review. I made the changes requested by the review team, and the plugin was approved on August 2, 2026. Receiving that approval meant far more to me than completing a technical process. I was now contributing my own code to the platform I had used for years. I had once been a user who installed plugins and changed settings; now I was the developer of a plugin that other WordPress users could install.</p>\n\n\n\n<p class=\"wp-block-paragraph\">OZD Katalog may not be the largest or most complex plugin in the WordPress ecosystem. Its value to me lies in the change it represents. It is my concrete answer to the question, “Can I really do this?” It showed me that blindness does not prevent me from creating and that, with suitable tools, patience, a willingness to learn, and honest feedback, I can contribute to open source.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-the-real-value-of-wordpress\">The Real Value Of WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress did not magically promise me financial freedom. It gave me something more fundamental and lasting: a place where I could publish ideas, build projects, and solve problems for clients and friends. On sadikozdogan.com.tr, I publish technical articles, share my projects, and pass on what I learn in Turkish. I work on other web projects, including imagefilex.com, and continue developing ideas for themes and plugins. Each project helps me establish a stronger and more independent place in the digital world.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I especially want to tell this story to disabled people, to people in Türkiye and similar environments who want to create technology, and to anyone who delays the first step because they do not feel qualified enough. You do not need to possess every answer before you begin. Accessibility barriers, financial limitations, the absence of a strong technical community around you, or the fear of making mistakes may slow your progress. Still, beginning with one small and genuine problem can eventually take you somewhere you never expected.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This is also what I value most about open source. You can learn from code someone else developed years ago, study documentation, work according to standards created by a community, and finally make your own contribution available to others. Becoming part of that chain is not simply a matter of publishing code. It means believing that knowledge can be shared and that people with different circumstances can participate in creating technology.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am now preparing to improve OZD Katalog with new features and language options. I also plan to continue building plugins, themes, and accessible applications. My goal is not only to release more products. I want to question how the tools I use work for blind users and, wherever possible, create solutions that are clear, lightweight, and accessible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My WordPress journey has taught me that the greatest barrier is not always a lack of technical knowledge. Sometimes the real barrier is believing that our voice and our work have little value. OZD Katalog began as a small idea, answered a real need, and became a plugin available to everyone through WordPress.org. For me, this is not an ending. It is a new beginning: a journey from user to creator, from hesitation to sharing, and from dreaming about contribution to actually making one.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h1 class=\"wp-block-heading\" id=\"turkce\">Ekranın Ötesinde Üretmek: WordPress, Erişilebilirlik ve OZD Katalog Hikâyem</h1>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress benim için yalnızca internet sitesi kurmaya yarayan bir içerik yönetim sistemi olmadı. Bana, görme engelli bir web geliştiricisi olarak kendi çalışma alanımı kurabileceğimi, karşılaştığım sorunlara çözüm üretebileceğimi ve dünyanın farklı yerlerindeki insanlarla aynı açık kaynak topluluğuna katkıda bulunabileceğimi gösterdi. <a href=\"https://haz.wordpress.org/plugins/ozd-katalog-eklentisi/\">OZD Katalog</a> eklentisinin WordPress.org’da yayımlanması ise bu uzun yolculuğun en görünür sonuçlarından biri oldu.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ben Sadık Özdoğan. <a href=\"https://www.google.com/maps/place/Ankara,+T%C3%BCrkiye/@38.7856907,30.5045406,7.28z/data=!4m6!3m5!1s0x14d347d520732db1:0xbdc57b0c0842b8d!8m2!3d39.9333635!4d32.8597419!16zL20vMGp5dw?entry=ttu&amp;g_ep=EgoyMDI2MDgyMy4wIKXMDSoASAFQAw%3D%3D\">Türkiye’nin Ankara</a> şehrinde yaşıyorum. <a href=\"https://www.google.com/maps/place/Eski%C5%9Fehir,+T%C3%BCrkiye/@39.2123552,31.4230128,7.55z/data=!4m6!3m5!1s0x14cc3e08220c0e5f:0xbc89395938049a08!8m2!3d39.7667061!4d30.5256311!16zL20vMDcyeWZ2?entry=ttu&amp;g_ep=EgoyMDI2MDgyMy4wIKXMDSoASAFQAw%3D%3D\">Eskişehir</a> <a href=\"https://www.anadolu.edu.tr/en\">Anadolu Üniversitesi</a> Web Tasarımı ve Kodlama Bölümünde eğitim aldım. Edebiyat, şiir ve müzik hayatımın önemli parçaları olsa da yıllar içinde web teknolojileri de benim için güçlü bir üretim alanına dönüştü. Görme engelli olduğum için bilgisayarı <a href=\"https://www.nvaccess.org/\">NVDA</a> ekran okuyucusuyla kullanıyorum. Ekrandaki görsel düzeni doğrudan görmek yerine sayfaların yapısını, başlıklarını, bağlantılarını, form alanlarını ve metinlerini ekran okuyucunun sesiyle takip ediyorum.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Bu çalışma biçimi bazen bir internet sitesindeki küçük bir erişilebilirlik hatasını bile büyük bir engele dönüştürebiliyor. Etiketi bulunmayan bir düğme, yanlış kurulmuş bir form, yalnızca görsel olarak anlaşılabilen bir uyarı ya da klavyeyle ulaşılamayan bir alan, başkaları için küçük bir kusur gibi görünürken benim için işlemi tamamen durdurabiliyor. Buna rağmen teknolojiyle arama mesafe koymak istemedim. Tam tersine, sistemlerin nasıl çalıştığını öğrenmeye ve kendi çözümlerimi üretmeye yöneldim.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress ile tanışmam bu arayışın önemli dönüm noktalarından biriydi. İlk yıllarda onu daha çok bir kullanıcı olarak tanıdım. Siteler kurdum, yazılar yayımladım, temaları özelleştirdim, eklentiler denedim ve karşılaştığım sorunlara çözümler aradım. Yönetim panelinin belirli bir düzene sahip olması ve birçok işlemin metinler, başlıklar ve standart form alanları üzerinden yürütülmesi benim için önemliydi. Her şey kusursuz derecede erişilebilir değildi; yine de WordPress, kendi içeriklerimi yayımlayabileceğim ve zamanla geliştirebileceğim açık bir alan sağladı.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Başlangıçta hazır tema ve eklentilerle çalışıyordum. Bir sorun çıktığında farklı ayarları deniyor, belge ve eğitimleri okuyup çözümü bulmaya çalışıyordum. Zamanla yalnızca bir aracı kullanan kişi olmakla yetinmediğimi fark ettim. Bir temada neden belirli bir davranışın ortaya çıktığını, bir fonksiyonun hangi dosyada çalıştığını ve bir özelliğin nasıl değiştirilebileceğini merak etmeye başladım. Küçük kod düzenlemeleriyle başlayan bu merak, beni giderek geliştirme tarafına taşıdı.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://generatepress.com/\">GeneratePress</a> üzerinde yaptığım özelleştirmeler ilk ciddi öğrenme alanlarımdan biri oldu. Önce kendi web sitemi geliştirdim. Ardından bir arkadaşım için radyo sitesi hazırladım. Farklı ihtiyaçlara göre temalar üzerinde çalıştım; haber, blog, firma ve radyo projeleri geliştirdim. Her proje yeni bir sorunla karşılaşmam, o sorunu parçalara ayırmam ve çalışan bir çözüm üretmem anlamına geliyordu. Çözdüğüm her ayrıntı teknik bilgimin yanında özgüvenimi de artırdı.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Görme engelli bir geliştirici olarak çalışma yöntemim bazı yönleriyle farklı. Kodun girintilerini ve sayfanın görsel görünümünü ekranı izleyerek kontrol edemiyorum. Dosyalar, satırlar ve bileşenler arasında klavyeyle dolaşıyorum; ekran okuyucunun aktardığı bilgiyi zihnimde bir yapıya dönüştürüyorum. Tasarımlarda güvendiğim kişilerden görsel geri bildirim alıyor, teknik kontrollerde ise standartlardan, test araçlarından ve tekrar tekrar denemekten yararlanıyorum. Bu süreç bana erişilebilirliğin yalnızca kullanıcı arayüzüne sonradan eklenen bir özellik olmadığını öğretti. Açık ve düzenli kod, doğru etiketler, anlaşılır metinler ve öngörülebilir davranışlar herkesin işini kolaylaştırıyor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Uzun süre kendi eklentimi yayımlama fikrim vardı. Fakat bu hedefin önünde teknik eksiklerden daha büyük bir engel bulunuyordu: Kendime yeterince güvenmiyordum. “Ya yapamazsam?”, “Ya kodum yetersiz bulunursa?”, “Ya eklentim reddedilirse?” gibi sorular beni başlangıç çizgisinde tutuyordu. İnsan bazen çalışmasının kusursuz olmasını beklerken onu hiç paylaşamayabiliyor. Benim için değişim, kusursuzluğu beklemek yerine öğrenerek ilerlemeyi kabul ettiğimde başladı.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yapay zekâ araçları da öğrenme sürecimde yardımcı oldu. Sorularımı daha ayrıntılı biçimde incelememi, kod parçalarını anlamamı, olası hataları görmemi ve fikirlerimi daha düzenli bir plana dönüştürmemi sağladı. Ancak benim yerime fikir üretmedi ya da projeyi tek başına kurmadı. İhtiyacı belirleyen, hangi özelliğin gerekli olduğuna karar veren, ortaya çıkan sonucu test eden ve sorumluluğunu alan bendim. Yapay zekâ, ekran okuyucu ve geliştirme araçları benim için aynı amaca hizmet eden yardımcılar oldu: Zihnimdeki fikri çalışan ve insanların kullanabileceği bir ürüne dönüştürmek.</p>\n\n\n\n<p class=\"wp-block-paragraph\">OZD Katalog fikri, bir sandalye firması için internet sitesi hazırlarken doğdu. Firmanın ürünlerini düzenli ve anlaşılır biçimde sunmak gerekiyordu. İlk olarak temanın içinde çalışan bir katalog yapısı hazırladım. Bu, yalnızca o projeye özel bir çözüm olabilirdi. Fakat çalışma ilerledikçe kendime şu soruyu sordum: “Neden bu yapıyı temanın içinde bırakayım? Neden bağımsız bir eklentiye dönüştürüp başka insanların da kullanmasını sağlamayayım?”</p>\n\n\n\n<p class=\"wp-block-paragraph\">Bu soru, OZD Katalog’un gerçek başlangıcı oldu. Amacım, e-ticaret sisteminin bütün karmaşıklığına ihtiyaç duymayan işletmelerin ürünlerini katalog biçiminde sergileyebilmesiydi. Bir ürünün adı, görseli, açıklaması, kategorisi ve gerekli bilgileri yönetim panelinden eklenebilmeli; ziyaretçi de bunları anlaşılır bir yapıda görebilmeliydi. Gerçek bir projede karşılaştığım ihtiyaç, başkalarının da yararlanabileceği genel bir çözüme dönüşmeye başladı.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Eklentinin ilk hâlini yaklaşık bir yıl önce hazırladım. Fakat çalışan bir kod ile WordPress.org’da yayımlanabilecek bir eklenti arasında büyük fark olduğunu öğrendim. Güvenlik kontrolleri, yetkilendirme, nonce kullanımı, veri temizleme ve çıktı kaçışlama gibi konuların dikkatle ele alınması gerekiyordu. Metinlerin çevrilebilir olması, eklenti dosyalarının doğru yapıda hazırlanması, kullanıcıya gösterilen ifadelerin anlaşılır olması ve WordPress kod standartlarına yaklaşılması gerekiyordu. Her düzeltme bana yalnızca eklentiyi değil, geliştirici olarak kendi çalışma disiplinimi de iyileştirme fırsatı verdi.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sonunda OZD Katalog’u WordPress.org incelemesine gönderdim. İnceleme ekibinin istediği düzeltmeleri uyguladım ve eklentim 2 Ağustos 2026 tarihinde onaylandı. Onay mesajını almak benim için teknik bir işlemin tamamlanmasından çok daha fazlasıydı. Yıllardır kullandığım WordPress’e artık kendi kodumla katkıda bulunuyordum. Bir zamanlar yalnızca eklenti kuran ve ayar yapan kullanıcıyken, artık başka kullanıcıların kurabileceği bir eklentinin geliştiricisiydim.</p>\n\n\n\n<p class=\"wp-block-paragraph\">OZD Katalog dünyanın en büyük ya da en karmaşık WordPress eklentisi olmayabilir. Benim için değeri, temsil ettiği değişimde yatıyor. Bu proje, “Acaba yapabilir miyim?” sorusuna verdiğim somut cevaptır. Görme engelli olmamın üretmeme engel olmadığını; doğru araçlar, sabır, öğrenme isteği ve geri bildirimle açık kaynak dünyasına katkı sunabileceğimi gösterdi.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress bana doğrudan finansal özgürlük vaat eden sihirli bir araç olmadı. Bana daha temel ve kalıcı bir şey verdi: Kendi fikirlerimi yayımlayabileceğim, projeler geliştirebileceğim, müşterilerin ve arkadaşlarımın ihtiyaçlarına çözüm üretebileceğim bir alan. sadikozdogan.com.tr üzerinde teknik yazılar yayımlıyor, geliştirdiğim projeleri paylaşıyor ve öğrendiklerimi Türkçe olarak başkalarına aktarıyorum. imagefilex.com gibi farklı web projeleri üzerinde çalışıyor, yeni tema ve eklenti fikirleri geliştiriyorum. Her proje dijital dünyada kendi yerimi biraz daha sağlamlaştırıyor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Bu hikâyeyi özellikle engelli bireylere, Türkiye’de ve benzer koşullarda teknoloji üretmek isteyenlere, kendisini yeterli görmediği için ilk adımı erteleyenlere anlatmak istiyorum. Başlamak için bütün cevaplara sahip olmak gerekmiyor. Erişilebilirlik sorunları, maddi sınırlamalar, çevrenizde yeterli teknik topluluğun bulunmaması veya hata yapma korkusu yolunuzu yavaşlatabilir. Fakat küçük ve gerçek bir sorunu çözerek başlamak, zamanla sizi tahmin etmediğiniz bir noktaya taşıyabilir.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Açık kaynak dünyasının benim için en güçlü yanı da budur. Bir başkasının yıllar önce geliştirdiği koddan öğrenebilir, belgeleri okuyabilir, topluluğun belirlediği standartlara göre çalışabilir ve sonunda kendi katkınızı başkalarının kullanımına açabilirsiniz. Bu zincirin bir parçası olmak, yalnızca kod yayımlamak değildir. Bilginin paylaşılabileceğine ve farklı koşullardaki insanların da üretime katılabileceğine inanmak demektir.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Şimdi OZD Katalog’u geliştirmeye, yeni özellikler ve dil seçenekleri eklemeye hazırlanıyorum. Bunun yanında başka eklentiler, temalar ve erişilebilir uygulamalar üzerinde çalışmayı planlıyorum. Hedefim yalnızca daha fazla ürün çıkarmak değil; kullandığım araçların görme engelli kullanıcılar açısından nasıl çalıştığını sorgulamak ve mümkün olduğunca anlaşılır, hafif ve erişilebilir çözümler üretmek.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress yolculuğum bana en büyük engelin her zaman teknik bilgi eksikliği olmadığını öğretti. Bazen asıl engel, kendi sesimizi ve emeğimizi değersiz görmemizdir. OZD Katalog küçük bir fikir olarak başladı, gerçek bir ihtiyaca cevap verdi ve sonunda WordPress.org’da herkesin erişebileceği bir eklentiye dönüştü. Benim için bu, bir bitiş değil; kullanıcı olmaktan üreticiye, çekinmekten paylaşmaya ve hayal etmekten katkı sunmaya uzanan yeni bir başlangıçtır.</p>\n<p>The post <a href=\"https://heropress.com/essays/building-beyond-the-screen-my-wordpress-accessibility-and-ozd-katalog-story/\">Building Beyond the Screen: My WordPress, Accessibility, and OZD Katalog Story &#8211; Ekranın Ötesinde Üretmek: WordPress, Erişilebilirlik ve OZD Katalog Hikâyem</a> appeared first on <a href=\"https://heropress.com\">HeroPress</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 02 Sep 2026 13:01:37 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Sadık Özdoğan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:44;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"Open Channels FM: Thanks to Omnisend for Their Continued Support\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560812\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://openchannels.fm/thanks-to-omnisend-for-their-continued-support/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:126:\"Omnisend continues its support for Open Channels FM, offering affordable services and fostering a strong community connection.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 02 Sep 2026 11:43:18 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:45;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:104:\"Open Channels FM: From Open Source to OpenAI WordPress and Halo Record Address Agent Security and Sprawl\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560773\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:111:\"https://openchannels.fm/from-open-source-to-openai-wordpress-and-halo-record-address-agent-security-and-sprawl/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:138:\"WordPress supports open-weight AI while enterprises address agent sprawl and new audit solutions like Halo Record offer verifiable trails.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 02 Sep 2026 08:45:35 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:46;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:106:\"WordPress Foundation: Announcing the 2026 Kim Parsell Memorial Scholarship Recipient: Jeanherline Santiago\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:42:\"https://wordpressfoundation.org/?p=2050739\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"https://wordpressfoundation.org/news/2026/2026-wcus-kim-parsell-scholarship-recipient/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3203:\"<p class=\"has-light-blue-background-color has-background wp-block-paragraph\" style=\"font-style: normal; font-weight: 700;\"><strong>Important note:</strong> Programs like the Kim Parsell Memorial Scholarship are made possible by the WordPress Foundation. Ongoing legal action by WP Engine threatens the Foundation&#8217;s ability to continue supporting scholarships, education programs, and community initiatives like this one.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;re proud to announce this year&#8217;s WordCamp US <a href=\"https://wordpressfoundation.org/kim-parsell-memorial-scholarship/\">Kim Parsell Memorial Scholarship</a> recipient, <strong>Jeanherline Santiago</strong>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">About Jeanherline</h2>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/wordpressfoundation.org/content/uploads/2026/09/765855621_18551815723076911_6518811318390439607_n.jpg?ssl=1\"><img alt=\"\" class=\"wp-image-2050742\" height=\"825\" src=\"https://i0.wp.com/wordpressfoundation.org/content/uploads/2026/09/765855621_18551815723076911_6518811318390439607_n.jpg?resize=660%2C825&#038;ssl=1\" width=\"660\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Jeanherline is a WordPress contributor who has translated strings for the Polyglots team and has volunteered and organized at WordCamps around the world. Professionally, she works as a web developer and digital strategist, leading web, SEO, and product work across Mori Web Studios and NarraSEO — with experience spanning complex WordPress development, technical SEO, local search, site performance, infrastructure, security, and SaaS.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Her work has supported clients and teams across the United States, Canada, Australia, and the Philippines, and she remains active in the global WordPress community through organizing, volunteering, and contributing at WordCamp events.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“WordPress has provided so many learning experiences for me where I have contributed, volunteered, met so many wonderful people, and grown both as a person and professionally. My involvement in the community, which once started off as a simple act of joining, has become one of the most significant aspects of my journey.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This scholarship being awarded to me in memory of Kim Parsell, with her legacy of being inclusive, supportive, and making a place for herself in the WordPress community, means so much to me” &#8211; Jeanherline Santiago</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/news/2019/11/people-of-wordpress-kim-parsell/\">Kim Parsell</a> made room for people. Her legacy lives on every time we make space for someone new. Congratulations, Jeanherline.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>The Kim Parsell Memorial Scholarship is funded entirely by the WordPress Foundation. If you&#8217;d like to help keep programs like this running, you can <a href=\"https://wordpressfoundation.org/donate/\">donate here</a>.</strong></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 01 Sep 2026 20:54:21 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Harmony Romo\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:47;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"Open Channels FM: Navigating Open Source Collaboration in the Age of AI\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560027\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"https://openchannels.fm/navigating-open-source-collaboration-in-the-age-of-ai/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:232:\"The rise of AI in open source software has expanded contributor diversity, necessitating improved communication and documentation to guide participants effectively while ensuring sustainable collaboration and high-quality resources.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 01 Sep 2026 09:20:12 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:48;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:122:\"Gutenberg Times: Building blocks without JavaScript, Accessibility Lab, AI plugin showdown and more —Weekend Edition 375\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=46992\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:128:\"https://gutenbergtimes.com/building-blocks-without-javascript-accessibility-lab-ai-plugin-showdown-and-more-weekend-edition-375/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:21839:\"<p class=\"wp-block-paragraph\">Hi, </p>\n\n\n\n<p class=\"wp-block-paragraph\">There is good news for me and good news for you. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The good news for me: with my five-year anniversary at Automattic, I get to go on a 3-month sabbatical, starting this week. It also means not only a break from Automattic but also from the WordPress community, a place that kept me engaged for the last 17 years. So that&#8217;s going to be a little weird for me. When I get back, I&#8217;ll let you know how it went. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The good news for you: my colleague <strong>Justin Tadlock</strong> will keep publishing Weekend Editions on Gutenberg Times while I am away. If you&#8217;ve read <a href=\"https://developer.wordpress.org/news/?author=20482\">his tutorials</a> on the WordPress Developer Blog or <a href=\"https://gutenbergtimes.com/author/jtadlock/\">his earlier posts here</a> on the Gutenberg Times, you know you&#8217;re in excellent hands. Not every week, but enough to tide you over during my pause.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, just to give serendipity a chance, I will be at <a href=\"https://athens.wordcamp.org/2026/en/\">WordCamp Athens</a> in December. Until then, all the best to you, your business and your family. I&#8217;ll be back. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Yours, <img alt=\"💕\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f495.png\" style=\"height: 1em;\" /><br /><em>Birgit</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/building-blocks-without-javascript-accessibility-lab-ai-plugin-showdown-and-more-weekend-edition-375/#0-word-press-release-information\">Developing Gutenberg and WordPress</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/building-blocks-without-javascript-accessibility-lab-ai-plugin-showdown-and-more-weekend-edition-375/#0-p\">Plugins and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/building-blocks-without-javascript-accessibility-lab-ai-plugin-showdown-and-more-weekend-edition-375/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/building-blocks-without-javascript-accessibility-lab-ai-plugin-showdown-and-more-weekend-edition-375/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/building-blocks-without-javascript-accessibility-lab-ai-plugin-showdown-and-more-weekend-edition-375/#wordpress-and-ai\">WordPress and AI</a></li></ul></nav>\n</div>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Karol Król</strong>&#8216;s first look walks you through <a href=\"https://www.youtube.com/watch?v=KUc0fGRuahA\">six features of WordPress 7.1</a> worth your attention: responsive styles, the new Tabs block, the Media Editor, the admin bar&#8217;s wider reach, hover and focus pseudo states, and the latest Notes updates. A useful orientation if you&#8217;ve been meaning to sit down with the release but haven&#8217;t had a chance to click around in the editor yet.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-972a13da wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><img alt=\"🎙\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f399.png\" style=\"height: 1em;\" /> The latest episode is <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-134-gutenberg-23-7-23-8-wordpress-7-1/\">Gutenberg Changelog #134 – Gutenberg 23.7, 23.8, WordPress 7.1 and more</a> with special guest <strong>Jessica Lyschik</strong>, Greyd. </p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46955\" height=\"367\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/Screenshot-2026-08-22-at-17.29.52.png?resize=1279%2C367&#038;ssl=1\" width=\"1279\" /></figure>\n\n\n\n<figure class=\"wp-block-embed is-type-rich is-provider-pocket-casts wp-block-embed-pocket-casts\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n</div>\n\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Change one header and it changes everywhere — that&#8217;s the part templates make easy and the part that trips people up. <strong>Wes Theron&#8217;</strong>s seven-minute walkthrough on <a href=\"https://www.youtube.com/watch?v=vuMPGulNw8g\"><strong>editing WordPress templates</strong></a> covers the difference between editing a page and editing its template, how to tell which template a page uses, and how to work through List View. Along the way you&#8217;ll remove titles across pages, add a site-wide banner, drop featured images from all posts, and reset a template when you&#8217;ve gone too far.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Your wp-admin, but as a desktop: <strong>OpenStation</strong> opens admin screens as <a href=\"https://github.com/WordPress/openstation\">draggable, resizable windows with a dock built from the admin menu</a>, plus virtual desktops, snap-to-grid, wallpapers, and a Cmd+K palette. It&#8217;s opt-in per user, patches nothing in core, and reverts completely on deactivation — the classic admin stays untouched for everyone else. Bundled extensions add a Monaco code editor, a cron manager, and an RSS reader. Available on the plugin directory as Desktop Mode, or try it in Playground. The plugin also inspired contributors to create three additional features for the Desktop mode: </p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://gutenbergtimes.com/wp-admin/plugin-install.php?tab=plugin-information&amp;plugin=odd-outlandish-desktop-decorator&amp;TB_iframe=true&amp;width=772&amp;height=849\">ODD — Apps for OpenStation</a> by Nick Hamze</li>\n\n\n\n<li><a href=\"https://gutenbergtimes.com/wp-admin/plugin-install.php?tab=plugin-information&amp;plugin=allterrain-photo-editor&amp;TB_iframe=true&amp;width=772&amp;height=849\">AllTerrain Photo Editor for OpenStation</a> by Daniel Lopez Sanchez</li>\n\n\n\n<li><a href=\"https://gutenbergtimes.com/wp-admin/plugin-install.php?tab=plugin-information&amp;plugin=deskbeat-for-desktop-mode&amp;TB_iframe=true&amp;width=772&amp;height=849\">Deskbeat for OpenStation</a> by <a href=\"https://profiles.wordpress.org/alexismp/\">alexismp</a></li>\n</ul>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-47039\" height=\"591\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/sOpenStation.png?resize=1024%2C591&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Built at WordCamp US Contributor Day, the <a href=\"https://github.com/topher1kenobe/WP-Photo-Directory-Importer\"><strong>Photo Directory Importer</strong></a> lets you search wordpress.org/photos from inside wp-admin and pull CC0 images into your Media Library. No API key, no account, and imports are deduplicated. In the block editor it&#8217;s a tab inside the Media Library modal rather than an entry next to Openverse and Pexels — so look one level deeper. Topher DeRosia and six co-contributors want testing before it goes to the .org repo.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">The admin bar takes up viewport space and makes every page you view slightly not the page your visitors see. The <a href=\"https://wordpress.org/news/2026/08/browser-extension/\"><strong>official WordPress browser extension</strong></a> hides it while keeping the shortcuts in your browser toolbar, and adds block outlines, a phone-sized preview, cache-busted reloads, and cookie clearing. <strong>Jake Goldman</strong> of HumanMade writes that nothing leaves your device. Chrome and Safari now, Firefox next. <strong>Ray Morey </strong>of The Repository <a href=\"https://www.therepository.email/official-wordpress-browser-extension-now-available-in-the-chrome-web-store-and-mac-app-store\">has more on its origins</a> as Goldman&#8217;s WP Detective side project.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Anne McCarthy</strong>&#8216;s <a href=\"https://www.therepository.email/new-accessibility-lab-plugin-prototype-lays-groundwork-for-accessibility-teams-first-canonical-plugin\"><strong>Accessibility Lab plugin prototype</strong></a> arrives with the Accessibility Team&#8217;s buy-in and a clear boundary: it&#8217;s a testing ground for features headed to core, not a substitute for fixing core. Three modules so far — Media Library view controls, real-time heading-order validation, and Troy Chaplin&#8217;s Block Accessibility Checks. <strong>Rae Morey</strong> traces how the idea won conditional support after 2025&#8217;s pushback, and where you can contribute.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Mitch Canter</strong>&#8216;s field guide to <a href=\"https://mitchcanter.me/wordpress-responsive-block-styles/\"><strong>responsive block styles in WordPress 7.1</strong></a> gets into the details the announcement posts skipped: the theme.json syntax, the two default viewports (@mobile at 480px and @tablet at 782px), and how to set your own breakpoints. You&#8217;ll also see <code>:hover</code> and <code>:focus</code> states — official only on Button and Navigation Link blocks so far — how the feature coexists with fluid typography and <code>clamp()</code> tokens, and a quick-reference table worth bookmarking.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-f711a01950e09a76 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>&#8220;This block contains unexpected or invalid content</em>&#8220;; if you maintain custom blocks, you&#8217;ve met that message. <strong>Paulo Carvajal</strong> collected <a href=\"https://gist.github.com/paulo-carvajal/2dbb789a95014245c420491eec517acd\"><strong>five WordPress block deprecation patterns</strong></a> in a GitHub Gist that cover most real cases: markup-only changes, attribute renames paired with <code>isEligible()</code> and <code>migrate()</code>, source changes, InnerBlocks restructuring, and stacked deprecations ordered newest-first. Each comes with copy-ready code, plus a reminder to test against real database content and keep old <code>save()</code> functions intact.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">You might have heard that building a custom block no longer requires React or a build pipeline. <strong>Fränk Klein</strong> tests <a href=\"https://css-tricks.com/wordpress-php-block-registration/\"><strong>PHP-only block registration in WordPress</strong></a> on CSS-Tricks: an <code>autoRegister</code> flag generates the editor JavaScript and sidebar controls for you, straight from the PHP registration. He&#8217;s honest about the limits (no in-preview editing, no live post data, three attribute types) and argues the real win is porting legacy widgets, shortcodes, and template parts into block themes with PHP skills you already have.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"wordpress-and-ai\">WordPress and AI</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Ask ten agencies whether they use AI and you&#8217;ll get ten yeses, <strong>Brad Williams</strong>, Co-Founder of WebDevStudios, notes in explaining <strong><a href=\"https://webdevstudios.com/2026/08/26/agentic-ai-development-wordpress/\">what agentic AI development means for your WordPress project</a>.</strong> Building on <strong>Alfredo Navas</strong>&#8216;s WordCamp US talk, &#8220;the model knows WordPress, it doesn&#8217;t know your WordPress&#8221;, William&#8217;s the post lays out three prerequisites: written project rules, documented processes, and scoped tool access, with a human reviewing everything. You also get five questions to ask any agency, including where your project&#8217;s knowledge lives when people leave.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Jonathan Bossenger</strong>&#8216;s latest live stream puts three viewer-suggested plugins through <strong><a href=\"https://www.youtube.com/watch?v=IC_0ZMlHFjI\">a WordPress AI plugin showdown</a>: </strong>Cross AI MCP Manager, Albert, and WP Vibe, judged on whether you can set each up without reading docs, connect it to a local site, and tell what data it sends home. WP Vibe routes everything through a third-party server, Albert won&#8217;t connect locally at all, and Cross AI — after real troubleshooting of its separate abilities and tools — is the only one working end to end.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-648bdf8497433be9 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--3\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-f3869868a647678f wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--4\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 29 Aug 2026 03:22:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:49;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"OpenStation Blog: We measured it: the desktop pays for itself by the third screen\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://openstation.blog/?p=463\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:99:\"https://openstation.blog/2026/08/28/we-measured-it-the-desktop-pays-for-itself-by-the-third-screen/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:7433:\"<p class=\"wp-block-paragraph\">OpenStation turns your WordPress admin into a desktop: windows, a dock, screens you can leave open while you work on something else. <a href=\"https://openstation.blog/2026/08/25/we-measured-it-openstation-windows-can-open-in-3-milliseconds/\">Last time we measured </a>how fast it starts. This time we went screen by screen, head to head against classic <code>wp-admin</code>, on the same site, the same account, the same sitting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Every number below was measured on the site you are reading right now, over a real network, on real WordPress.com hosting.</p>\n\n\n\n<h2 class=\"wp-block-heading\">The short version</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>Opening a screen:</strong> 25% to 54% less time in the browser, on all four screens we tried.</li>\n\n\n\n<li><strong>Going back to a screen you already have open:</strong> instant, because nothing reloads. Classic makes you wait 2.4 to 3.7 seconds for the same thing.</li>\n\n\n\n<li><strong>Starting the desktop:</strong> about 1.7 seconds slower than a classic Dashboard, once. That one goes to classic <code>wp-admin</code>, and we will come back to it.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Opening a screen</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This is the part you feel all day. The numbers are the time the browser spent, measured as load minus time-to-first-byte (<a href=\"https://web.dev/articles/ttfb\">TTFB</a>). Subtracting TTFB takes the hosting out of it: the server does the same work either way, so what is left is the part we are responsible for.</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>Screen</th><th>OpenStation</th><th>Classic wp-admin</th><th>Difference</th></tr></thead><tbody><tr><td>Posts</td><td>1172 ms</td><td>1559 ms</td><td>25% less</td></tr><tr><td>Media</td><td>823 ms</td><td>1528 ms</td><td>46% less</td></tr><tr><td>Plugins</td><td>782 ms</td><td>1711 ms</td><td>54% less</td></tr><tr><td>Post editor</td><td>895 ms</td><td>1960 ms</td><td>54% less</td></tr></tbody></table><figcaption class=\"wp-element-caption\">Time in the browser after the first byte. Medians, nine samples per screen (five for the editor).</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The heavier the screen, the bigger the gap. The post editor, the heaviest thing in <code>wp-admin</code>, saves the most: about a second, every time you open a post. TTFB stayed level between the two, within 100 ms on every screen, which is what you would expect when the server is doing identical work.</p>\n\n\n\n<h2 class=\"wp-block-heading\">We checked whether the averages were lying</h2>\n\n\n\n<p class=\"wp-block-paragraph\">A median can hide a lot, so here is every sample, slowest to fastest. On three of the four screens the two ranges never touch: our slowest run still beat their fastest one.</p>\n\n\n\n<figure class=\"wp-block-table\"><table><thead><tr><th>Screen</th><th>OpenStation</th><th>Classic wp-admin</th><th>Overlap</th></tr></thead><tbody><tr><td>Posts</td><td>740 to 1381 ms</td><td>1220 to 2012 ms</td><td>slight</td></tr><tr><td>Media</td><td>606 to 1235 ms</td><td>1363 to 1916 ms</td><td>none</td></tr><tr><td>Plugins</td><td>502 to 1052 ms</td><td>1384 to 1867 ms</td><td>none</td></tr><tr><td>Post editor</td><td>701 to 1243 ms</td><td>1510 to 2293 ms</td><td>none</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Posts is the only screen where the two graze each other. Everywhere else there is clean air between them.</p>\n\n\n\n<h2 class=\"wp-block-heading\">The part where we lose</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The desktop has to boot before it can show you anything, and classic <code>wp-admin</code> does not. Loading the shell with the Dashboard in a window took 7.2 seconds, against 5.5 for the classic Dashboard. That is about 1.7 seconds more, once, when you arrive.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Then it starts paying you back. Every screen you open gives back roughly 760 ms, so you are ahead by the third one, and each time you return to something already open you save another 2.5 seconds. Three screens and you have broken even. A working morning is not close.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Why it is faster</h2>\n\n\n\n<p class=\"wp-block-paragraph\">None of this is a measurement trick, it is just how the two work. Classic <code>wp-admin</code> throws the whole admin away every time you click: the menu, the toolbar, the shared scripts and styles, rebuilt from scratch, every time. OpenStation loads that once and keeps it. A window then fetches a stripped-down admin page that does not build the toolbar or the menu at all, and whose stylesheets were already fetched the first time you opened it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And going back to an open window is not a page load at all. It is a focus change, so there is nothing to wait for.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How we measured it</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>One site, one account, one sitting.</strong> The two sides alternated in blocks, so a slow minute on the host hits both of them equally.</li>\n\n\n\n<li><strong>The same metric on both sides.</strong> Both report <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/PerformanceNavigationTiming\">PerformanceNavigationTiming</a> from the document you are actually looking at. For OpenStation that is the window&#8217;s own document. No mismatched metrics, no thumb on the scale.</li>\n\n\n\n<li><strong>A real baseline.</strong> Classic <code>wp-admin</code> was rendered on this same site through a per-request flag, checked on every sample: no desktop, with the admin menu and toolbar exactly where they should be.</li>\n\n\n\n<li><strong>Two samples binned.</strong> Two classic readings were taken before the load event had fired, so Posts has seven samples on that side instead of nine.</li>\n\n\n\n<li><strong>Warm cache, live host.</strong> TTFB wandered between 788 and 1825 ms across the session, which is exactly why we report it separately.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">One thing we did not measure: a properly cold cache. Emptying it properly also means clearing the site data, which signs you out, and that was not something we were going to do before every single sample on a live site. It is the rarer case anyway. You pay for a cold cache once per browser, not once per session, so the warm numbers are the ones you actually live with.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Everything above is OpenStation 1.1.4, measured against classic <code>wp-admin</code> on the same site. It is the desktop against the classic admin, not one release against another.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And if you don&#8217;t believe me, watch these YouTube videos:</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-9-16 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\" style=\"font-size: 16px;\">Note: AI was used for the measurement and the first draft, I did the editing. If you want the method and every number we collected, the technical report <a href=\"https://claude.ai/code/artifact/77dc792c-66b0-4082-b420-e4d97d781a03\">is here</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 28 Aug 2026 18:15:27 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Roberto Aranda\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:9:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Fri, 25 Sep 2026 01:08:01 GMT\";s:12:\"content-type\";s:8:\"text/xml\";s:13:\"last-modified\";s:29:\"Fri, 25 Sep 2026 01:00:37 GMT\";s:4:\"vary\";s:15:\"Accept-Encoding\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:2:\"br\";s:7:\"al